    public void CommandHWDeviceID() {
        byte[] cmdGetDeviceID = new byte[1];
        cmdGetDeviceID[0] = COMMAND_GET_DEVICE_ID_BYTE;
        int result;
        byte[] cmdSetDeviceID = new byte[5];
        long lDeviceID;

        if(mUsbDeviceConnection == null){
            Toast.makeText(getBaseContext(), "inputstream == null || outputstream == null", Toast.LENGTH_SHORT).show();
            return;
        }

        for (int i = 0; i < 3; i++) {
            mUsbDeviceConnection.bulkTransfer(endpointDataOut, cmdGetDeviceID, 1, 0);
            try {
                Thread.sleep(50);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
           // byte[] myBufferIn = new byte[10];
            byte[] myBufferIn = new byte[64];
            result = mUsbDeviceConnection.bulkTransfer(endpointDataIn, myBufferIn, myBufferIn.length, 0);
            if (result >= 9) {
                //https://www.ftdichip.com/Support/Knowledgebase/index.html?an232b_04smalldataend.htm
                //The buffer is made up of 2 status bytes and 4 user bytes.
                byte Status0 = myBufferIn[0];
                byte Status1 = myBufferIn[1];
//                if ((myBufferIn[2] == VERSION_PACKET_HEADER)
//                        && (myBufferIn[3] > 0) && (myBufferIn[3] < 10)
//                        && (myBufferIn[4] < 10)) {
                if (myBufferIn[2] == VERSION_PACKET_HEADER) {
                    HWMainVersion = myBufferIn[3];
                    HWSubVersion = myBufferIn[4];

                    HWDeviceID[0] = myBufferIn[5];
                    HWDeviceID[1] = myBufferIn[6];
                    HWDeviceID[2] = myBufferIn[7];
                    HWDeviceID[3] = myBufferIn[8];

                    long lTemp;
                    lTemp = ((long) HWDeviceID[0] & 0x00FF);
                    lTemp = lTemp << 8;
                    lTemp = lTemp | ((long) HWDeviceID[1] & 0x00FF);
                    lTemp = lTemp << 8;
                    lTemp = lTemp | ((long) HWDeviceID[2] & 0x00FF);
                    lTemp = lTemp << 8;
                    lTemp = lTemp | ((long) HWDeviceID[3] & 0x00FF);
                    System.out.println(String.valueOf(lTemp));
                    if (lTemp == 0) {
                        cmdSetDeviceID[0] = COMMAND_SET_DEVICE_ID_BYTE;
                        Calendar c = Calendar.getInstance();
                        lTemp = c.getTimeInMillis();
                        lTemp = lTemp / 1000;
                        cmdSetDeviceID[4] = (byte) (lTemp & 0x000000FF);
                        lTemp = lTemp >> 8;
                        cmdSetDeviceID[3] = (byte) (lTemp & 0x000000FF);
                        lTemp = lTemp >> 8;
                        cmdSetDeviceID[2] = (byte) (lTemp & 0x000000FF);
                        lTemp = lTemp >> 8;
                        cmdSetDeviceID[1] = (byte) (lTemp & 0x000000FF);
                        mUsbDeviceConnection.bulkTransfer(endpointDataOut, cmdSetDeviceID, 5, 0);
                        try {
                            Thread.sleep(50);
                        } catch (InterruptedException e) {
                            e.printStackTrace();
                        }
                    } else {
                        lDeviceID = lTemp * 1000;
                        SimpleDateFormat sdf1 = new SimpleDateFormat("yyMMddHHmmss", Locale.ENGLISH);
                        Calendar cal = Calendar.getInstance();
                        cal.setTimeInMillis(lDeviceID);
                        StrHWDeviceID = sdf1.format(cal.getTime());// all done
                        SaveHWVersion();
                        break;
                    }
                }
            }
        }
    }

    private void setUsbDevice(UsbDevice device) {
        if (device != null) {
            UsbManager usbm = (UsbManager) getSystemService(USB_SERVICE);

            //interface0, endpoints=2, commc
            UsbInterface intfControl = device.getInterface(0);
//            UsbEndpoint endpointXferBulkIn = intfControl.getEndpoint(0);
//            System.out.println(String.valueOf(endpointXferBulkIn.getDirection()));
//            System.out.println(String.valueOf(endpointXferBulkIn.getType()));
            endpointDataIn = intfControl.getEndpoint(0);
//            UsbEndpoint endpointXferBulkOut = intfControl.getEndpoint(1);
//            System.out.println(String.valueOf(endpointXferBulkOut.getDirection()));
//            System.out.println(String.valueOf(endpointXferBulkOut.getType()));
            endpointDataOut = intfControl.getEndpoint(1);

            try {
                mUsbDeviceConnection = usbm.openDevice(device);
                if(mUsbDeviceConnection.claimInterface(intfControl, true)) {
                    mUsbDevice = device;
                    mUsbDeviceConnection.controlTransfer(0x40, 0, 0, 0, null, 0, 0);// reset
                    mUsbDeviceConnection.controlTransfer(0x40, 0, 1, 0, null, 0, 0);// clear Rx
                    mUsbDeviceConnection.controlTransfer(0x40, 0, 2, 0, null, 0, 0);// clear Tx
//                    mUsbDeviceConnection.controlTransfer(0x40, 0x03, 0x001A, 0, null, 0, 0);//Baud rate 115200
                    mUsbDeviceConnection.controlTransfer(0x40, 0x03, 0x0034, 0, null, 0, 0);//Baud rate 57600

//                    AsyncCallWS_UsbDeviceDataComm taskUsbDeviceDataComm = new AsyncCallWS_UsbDeviceDataComm();
//                    taskUsbDeviceDataComm.execute();
//                    StartAcqisition();
                } else {
                    mUsbDeviceConnection.close();
                    mUsbDeviceConnection = null;
                    Toast.makeText(this, "UsbDeviceConnection failed to claimInterface.", Toast.LENGTH_SHORT).show();
                }
            } catch (Exception e) {

            }
        }
    }

