    public void SaveHWVersion() {
        esygDbHelper mDbHelper = new esygDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();
        ContentValues values2 = new ContentValues();
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_HWMainVersion, String.valueOf(HWMainVersion));
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_HWSubVersion, String.valueOf(HWSubVersion));
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_ECGUpdateIntervalMSec, String.valueOf(ECGUpdateIntervalMSec));
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_StrHWDeviceID, StrHWDeviceID);
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_strI2I_PhysicianName, strI2I_PhysicianName);
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_strI2I_PhysicianPassword, strI2I_PhysicianPassword);
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_strI2I_InstitutionGUID, strI2I_InstitutionGUID);
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_strI2I_FTPUser, strI2I_FTPUser);
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_strI2I_FTPPassword, strI2I_FTPPassword);
        values2.put(esygDbContract.HWMaster.COLUMN_NAME_strI2I_FTPPath, strI2I_FTPPath);

        // Insert single row, returning the primary key value of the row
        long lTemp2 = db.update(esygDbContract.HWMaster.TABLE_NAME, values2, null, null);
        if(lTemp2 <= 0) {
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient1ID, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient1Used, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient2ID, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient2Used, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient3ID, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient3Used, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient4ID, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient4Used, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient5ID, 0);
            values2.put(esygDbContract.HWMaster.COLUMN_NAME_OfflinePatient5Used, 0);
            lTemp2 = db.insert(esygDbContract.HWMaster.TABLE_NAME, null, values2);
        }
        db.close();
    }

