    public void ReadPatientSampleList() {
        esygDbHelper mDbHelper = new esygDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getReadableDatabase();
        String[] projection1 = {
                esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleTimestamp,
                esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientList,
                esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleList,
                esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleStatus,
                esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleReferred,
                esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleComments,
        };
        String sortOrder1 = esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleTimestamp + " DESC";
        Cursor c1 = db.query(
                esygDbContract.PatientSamplesDB.TABLE_NAME,  // The table to query
                projection1,                               // The columns to return
                null,                                // The columns for the WHERE clause
                //    	    selectionArgs,                            // The values for the WHERE clause
                null,
                null,                                     // don't group the rows
                null,                                     // don't filter by row groups
                sortOrder1                                 // The sort order
        );

        alECGScan.clear();
        clsECGSample newScan0 = new clsECGSample();
        newScan0.lScanTimestamp = 0;
        newScan0.strPatient = "Select Patient";
        newScan0.strScan = "";
        newScan0.iStatus = SAMPLE_STATUS_NONE;
        newScan0.Referred = false;
        newScan0.strComments = "";
        alECGScan.add(newScan0);

        if (c1 != null && c1.moveToFirst()) {
            if (c1.getCount() > 0) {
                int iCount = c1.getCount();
                for(int i=0; i<iCount; i++) {
                    try {
                        clsECGSample newScan = new clsECGSample();
                        newScan.lScanTimestamp = c1.getLong(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleTimestamp));
                        newScan.strPatient = c1.getString(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientList));
                        newScan.strScan = c1.getString(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleList));
                        newScan.iStatus = c1.getInt(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleStatus));
                        newScan.Referred  = Boolean.valueOf(c1.getString(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleReferred)));
                        newScan.strComments = c1.getString(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleComments));
//                        byte[] bytePatientSampleData = c1.getBlob(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleData));

                        alECGScan.add(newScan);
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                    c1.moveToNext();
                }
            }
        }

        db.close();
    }
