    public void UpdatePatientSampleFile(int iIndex) {
        esygDbHelper mDbHelper = new esygDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();
        ContentValues values1 = new ContentValues();
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleTimestamp, alECGScan.get(iIndex).lScanTimestamp);
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientList, alECGScan.get(iIndex).strPatient);
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleList, alECGScan.get(iIndex).strScan);
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleStatus, alECGScan.get(iIndex).iStatus);
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleReferred, String.valueOf(alECGScan.get(iIndex).Referred));
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleComments, alECGScan.get(iIndex).strComments);
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleDrSignURL, alECGScan.get(iIndex).strDrSignURL);
        values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleDrSignSizeBytes, alECGScan.get(iIndex).iDrSignSizeBytes);

        String whereClause = esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleList + "=" + "'" + alECGScan.get(iIndex).strScan + "'";
        long lTemp1 = db.update(esygDbContract.PatientSamplesDB.TABLE_NAME, values1, whereClause, null);
        if(lTemp1 <= 0) {
            lTemp1 = db.insert(esygDbContract.PatientSamplesDB.TABLE_NAME, null, values1);
        }
        db.close();
    }
