                                        Str1 = tableRow.get("Patient_Mobile1").toString();
                                        Str2 = tableRow.get("Patient_DOB").toString().substring(0, 10);
                                        Str3 = tableRow.get("Patient_Fname").toString();
                                        Str4 = tableRow.get("Patient_Mname").toString();
