                                        tv2.setText(Str2);
                                        tv2.setTextSize(getResources().getDimension(R.dimen.TextSizeSearchResults));
                                        tv2.setTextColor(tvRef.getTextColors());
                                        tblRow.addView(tv2);

                                        TextView tv3 = new TextView(getApplicationContext());
                                        if( Str3.equalsIgnoreCase("anyType{}"))
                                            Str3 = "";
