    private class AsyncCallWS_PreviewECG extends AsyncTask<String, Void, Void> {
        @Override
        protected void onPreExecute() {
            Button button = (Button) findViewById(R.id.ButtonExit);
            button.setEnabled(false);
            button = (Button) findViewById(R.id.ButtonGain);
            button.setEnabled(false);
            button = (Button) findViewById(R.id.ButtonSpeed);
            button.setEnabled(false);
            button = (Button) findViewById(R.id.ButtonQRSLead);
            button.setEnabled(false);
            button = (Button) findViewById(R.id.ButtonPreviewSend);
            button.setEnabled(false);

            byte[] command2 = new byte[1];
            command2[0] = COMMAND_STOP_BYTE;
            USBDataStreamIn = false;
            try {
                if (mUsbDeviceConnection != null) {
                    mUsbDeviceConnection.bulkTransfer(endpointDataOut, command2, 1, 0);
                } else {
                }
            } catch (Exception e2) {
                // TODO Auto-generated catch block
                e2.printStackTrace();
            }
        }
        @Override
        protected void onProgressUpdate(Void... values) {
        }
        @Override
        protected Void doInBackground(String... strings) {
            while (mNewDataReceived);
            //Wait till background Server-Sync thread is busy
            while(!SyncServerThreadSleep) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
            SyncServerEnable = false;

            return null;
        }
        @Override
        protected void onPostExecute(Void result) {
            mNextByte = 0;
            mCommState = COMM_STATE_VERSION_HEADER;

            glSurfaceView.onPause();
            glSurfaceView.surfaceDestroyed(glSurfaceView.getHolder());
            glRenderer.SyncObj.release();
            glRenderer = null;

            SelectQRSLead_CalculateHR(acqScan);
            acqScan.HRCopy = Measurement.current_HR;
            lead_no = QRSLeadIndex; //vnp 2 june 16
            System.out.println("QRSLeadIndex = " + String.valueOf(QRSLeadIndex));
            if (acqScan.HRCopy > 0) {
                //vnp 2 june 16  for (lead_no = 0; lead_no < 12; lead_no++)
                Measure.Calculate_Median(getBaseContext(), acqScan);

                //vnp 2 june 16   for (lead_no = 0; lead_no < 12; lead_no++)
                Measure.GetMeasurements(getBaseContext());
                for (int i = 0; i < 12; i++)  //vnp 2 june 16
                    Measure.CalculateAmplitudes((short) i);

                Measure.Measure_axis(); //vnp 26 nov 15

                Measure.Calculate_Interpretation(QRSLeadIndex);
            } else {
                Measure.strInterpretation_Status = "";
                for (int i = 0; i < Measure.nInterpretation_Status.length; i++) {
                    //                                Measure.nInterpretation_Status[i] = 0;
                    Measure.nInterpretation_Status[i] = 9;  //bmp 28 dec 16
                }
            }

            if (!DataSavedLocally) {
                SaveECGDataLocally(false, true);
            }

            SaveMeasurementDataDB(acqScan);

            PrevLayoutResourceID = R.layout.activity_aquire;
            InitEcgPreview();
        }
    }
    private void InitEcgPreview() {
        currentPatient = new clsPatient();
        switch(currentPatientType) {
            case ESY_G_OFFLINE_PATIENT:
                currentPatient = OfflinePatient;
                break;
            case ESY_G_ONLINE_PATIENT:
                currentPatient = OnlinePatient;
                break;
            case ESY_G_EMERGENCY_PATIENT:
                currentPatient = EmergencyPatient;
                break;
        }

        ParseECGReportDB(acqScan, currentPatient);

//***************  reduntant code  psy 01/06/2026
/*
        SelectQRSLead_CalculateHR(acqScan);

        HRCopy = Measurement.current_HR;
        lead_no=QRSLeadIndex; //vnp 2 june 16
        if(HRCopy > 0) {
            //vnp 2 june 16  for (lead_no = 0; lead_no < 12; lead_no++)
            Measure.Calculate_Median(getBaseContext(), acqScan);

            //vnp 2 june 16   for (lead_no = 0; lead_no < 12; lead_no++)
            Measure.GetMeasurements(getBaseContext());
            for(int i=0; i<12; i++)  //vnp 2 june 16
                Measure.CalculateAmplitudes((short)i);

            Measure.Measure_axis(); //vnp 26 nov 15

            Measure.Calculate_Interpretation(QRSLeadIndex);
        } else {
            Measure.strInterpretation_Status = "";
        }
*/

        ParseMeasurementReportDB(acqScan);   //Necessary for prn_current_HR

        try {
            HRCopy = Short.parseShort(acqScan.prn_current_HR.trim());
        } catch (Exception e) {
            HRCopy = 0;
        }
///////////////////////////////////////////
//        String StrPDFReportPreview = baseDir + "/data/" + "Preview" + ".pdf";
        String StrPDFReportPreview = getBaseContext().getCacheDir() + File.separator + "Preview" + ".pdf";
        // create a new document
        PdfDocument document = new PdfDocument();
        // crate a page description
        PdfDocument.PageInfo pageInfo = new PdfDocument.PageInfo.Builder(841, 595, 1).create();
        // start a page
        PdfDocument.Page page = document.startPage(pageInfo);
        // draw something on the page
        MyPrintDocumentAdapter pda = new MyPrintDocumentAdapter(this);
        pda.RotateDeg = 0;
        pda.drawPagePreviewEcg_3By4(page, currentPatient, acqScan);
        // finish the page
        document.finishPage(page);
        // write the document content
        File PdfFile = new File(StrPDFReportPreview);

        try {
            try (FileOutputStream fos = new FileOutputStream(PdfFile)) {
                document.writeTo(fos);
                fos.flush();
            }

            String StrTMPReportUpload = getBaseContext().getCacheDir()
                    + File.separator + acqScan.strScanFileName + ".tmp";

            File TmpFile = new File(StrTMPReportUpload);

            copyFile(PdfFile, TmpFile);

        } catch (FileNotFoundException e) {
            e.printStackTrace();
            Toast.makeText(getBaseContext(), "PDF file create failed", Toast.LENGTH_SHORT).show();
        } catch (IOException e) {
            e.printStackTrace();
            Toast.makeText(getBaseContext(), "PDF write failed", Toast.LENGTH_SHORT).show();
        } finally {
            document.close();
        }
///////////////////////////////////////////
        setContentView(R.layout.activity_ecgpreview);
        CurrentLayoutResourceID = R.layout.activity_ecgpreview;

        RefreshStatus();
        if(PrevLayoutResourceID == R.layout.activity_aquire) {
            Button bt = (Button) findViewById(R.id.ButtonExitEcgPreview);
            bt.setEnabled(true);
            bt = (Button) findViewById(R.id.ButtonPrintA4EcgPreview);
            bt.setEnabled(PrintBeforeSend);
//            bt = (Button) findViewById(R.id.ButtonPrintThermalEcgPreview);
//            bt.setEnabled(PrintBeforeSend);
            bt = (Button) findViewById(R.id.ButtonSend);
            bt.setEnabled(true);

            TextView tv = (TextView) findViewById(R.id.textViewCommentsLabel);
            tv.setVisibility(View.INVISIBLE);
            EditText et = (EditText) findViewById(R.id.editTextPreviewComments);
            et.setEnabled(false);
            et.setVisibility(View.INVISIBLE);
        }

        try {
            File imageFile = new File(StrPDFReportPreview);

            // create a new renderer
            renderer = new PdfRenderer(ParcelFileDescriptor.open(imageFile, ParcelFileDescriptor.MODE_READ_ONLY));
            renderer_page = renderer.openPage(0);

            Display display = getWindowManager().getDefaultDisplay();
            DisplayMetrics metrics = new DisplayMetrics();
            display.getMetrics(metrics);
            int DisplayWidth = metrics.widthPixels;
            int DisplayHeight = metrics.heightPixels;

            mBitmap = Bitmap.createBitmap(renderer_page.getWidth(), renderer_page.getHeight(), Bitmap.Config.ARGB_8888);
            renderer_page.render(mBitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);

            CustomImageView2 mImageView = (CustomImageView2)findViewById(R.id.customImageVIew1);
            mImageView.setImageBitmap(mBitmap);
            mImageView.setAdjustViewBounds(true);
            mImageView.invalidate();

            renderer_page.close();
            renderer.close();

            ImageButton imgbtn = (ImageButton) findViewById(R.id.imageButtonZoomEcgPreview);
            imgbtn.performClick();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

