    public void UploadEcg() {
        String strUrl = "";
        try {
            String[] strSplit4 = strServerIP.split("\\.");
            if(strSplit4.length == 4) {
//bmp 05-Aug-25
//                strUrl = "http://" + strServerIP + ":90" + NASAN_I2I_URL_uploadecg;
                strUrl = "http://" + strServerIP + NASAN_I2I_URL_uploadecg;
//bmp 05-Aug-25
            } else {
                strUrl = "https://" + strServerIP + NASAN_I2I_URL_uploadecg;
            }
            byte[] bytearraydata = new byte[161 + (SIZEOF_RECORD_BUFFER * 2 * 12)];
            byte[] bytearraysignal = new byte[0];
            for (int j = 1; j < CollectedSampleList.size(); j++) {
                String StrPatientSample = CollectedSampleList.get(j);

                esygDbHelper mDbHelper = new esygDbHelper(getBaseContext());
                // Gets the data repository in write mode
                SQLiteDatabase db = mDbHelper.getReadableDatabase();
                String[] projection1 = {
                        esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleData,
                };
                String selection1 = esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleList + "=" + "'" + StrPatientSample + "'";
                Cursor c1 = db.query(
                        esygDbContract.PatientSamplesDB.TABLE_NAME,  // The table to query
                        projection1,                               // The columns to return
                        selection1,                                // The columns for the WHERE clause
                        //    	    selectionArgs,                            // The values for the WHERE clause
                        null,
                        null,                                     // don't group the rows
                        null,                                     // don't filter by row groups
                        null                                 // The sort order
                );

                if (c1 != null && c1.moveToFirst()) {
                    if (c1.getCount() > 0) {
                        try {
                            bytearraydata = c1.getBlob(c1.getColumnIndexOrThrow(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleData));
                        } catch (Exception e) {
                            e.printStackTrace();
                        }
                    }
                }
                db.close();

                String StrECGFileName = StrPatientSample + ".ecg";
//bmp 21-Nov-25
               /* String StrTMPFileName = StrPatientSample + ".tmp";
//                String StrPDFFileName = StrPatientSample + ".pdf";
                                byte[] bytearraytmp = new byte[0];
                byte[] bytearraypdf = new byte[0];
//                File pdfFile = new File(baseDir + "/data/" + StrPatientSample + ".pdf");
                File pdfFile = new File(getBaseContext().getCacheDir() + File.separator + StrPatientSample + ".pdf");
                if(pdfFile.exists()) {
                    int iLength = (int) pdfFile.length();
                    bytearraypdf = new byte[iLength];
                    FileInputStream inputStream = null;
                    try {
                        inputStream = new FileInputStream(pdfFile);
                        inputStream.read(bytearraypdf);
                        inputStream.close();
                    } catch (FileNotFoundException e) {
                        throw new RuntimeException(e);
                    } catch (IOException e) {
                        throw new RuntimeException(e);
                    }
                }*/
                String StrTMPFileName = StrPatientSample + ".tmp";
                byte[] bytearraytmp = new byte[0];

                File tmpFile = new File(getBaseContext().getCacheDir()
                        + File.separator + StrPatientSample + ".tmp");

                if (tmpFile.exists()) {
                    int iLength = (int) tmpFile.length();
                    bytearraytmp = new byte[iLength];

                    FileInputStream inputStream = new FileInputStream(tmpFile);
                    inputStream.read(bytearraytmp);
                    inputStream.close();
                }
//bmp 21-Nov-25
                OkHttpClient client = new OkHttpClient().newBuilder()
                        .readTimeout(60, TimeUnit.SECONDS)
                        .connectTimeout(60, TimeUnit.SECONDS)
                        .build();
                MediaType mediaType = MediaType.parse("text/plain");
                RequestBody body = new MultipartBody.Builder().setType(MultipartBody.FORM)
                        .addFormDataPart("files",StrECGFileName,
                                RequestBody.create(MediaType.parse("application/octet-stream"),
                                        bytearraydata))
//bmp 21-Nov-25
//                        .addFormDataPart("files",StrTMPFileName,
//                                RequestBody.create(MediaType.parse("application/octet-stream"),
//                                        bytearraysignal))
                        .addFormDataPart("files", StrTMPFileName,
                                RequestBody.create(MediaType.parse("application/octet-stream"),
                                        bytearraytmp))
//bmp 21-Nov-25
                        .build();
                Request request = new Request.Builder()
                        .url(strUrl)
                        .method("POST", body)
                        .addHeader("token", NasanI2I_Token)
                        .build();
                Response response = client.newCall(request).execute();
                int responseCode = response.code();
                if (responseCode == 200) {
                    InputStream in = new BufferedInputStream(response.body().byteStream());
                    BufferedReader br = new BufferedReader(new InputStreamReader(in));
                    String strOutput;
                    while ((strOutput = br.readLine()) != null) {
                        System.out.println(strOutput);
                        JSONObject jo = new JSONObject(strOutput);
                        if (jo.getString("message").equalsIgnoreCase("Files uploaded successfully!")) {
                            JSONArray joArr = (JSONArray) jo.get("files");
                            if(joArr.length() == 2) {
//bmp 21-Nov-25
//                                if(bytearraydata.length == joArr.getJSONObject(0).getInt("size")) {
                                if(     (bytearraydata.length == joArr.getJSONObject(0).getInt("size")) &&
                                        (bytearraytmp.length == joArr.getJSONObject(1).getInt("size"))) {
//                                    pdfFile = new File(baseDir + "/data/" + StrPatientSample + ".pdf");
                                    tmpFile = new File(getBaseContext().getCacheDir() + File.separator + StrPatientSample + ".tmp");
                                    if (tmpFile.exists()) {
                                        tmpFile.delete();
                                    }
//bmp 21-Nov-25
                                    String Str = CollectedSampleList.get(j);
                                    String strPurpose = String.valueOf(CollectionPurposeList.get(j));
                                    for (int i = 1; i < alECGScan.size(); i++) {
                                        if (Str.equalsIgnoreCase(alECGScan.get(i).strScan)) {
                                            int iTemp = alECGScan.get(i).iStatus;
                                            iTemp |= SAMPLE_STATUS_UPLOADED;
                                            if(strPurpose.equalsIgnoreCase("true"))
                                                iTemp |= SAMPLE_STATUS_REFERRED;
                                            alECGScan.get(i).iStatus = iTemp;

                                            UpdatePatientSampleFile(i);
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    br.close();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void onClickEcgPreview(View v) {
        CustomImageView2 mImageView;

        switch (v.getId()) {
            case R.id.imageButtonRestoreEcgPreview:
                //restore Imageview to initial state
                mImageView = (CustomImageView2)findViewById(R.id.customImageVIew1);
                mImageView.setAdjustViewBounds(true);
                mImageView.invalidate();
                break;
            case R.id.imageButtonZoomEcgPreview:
                mImageView = (CustomImageView2)findViewById(R.id.customImageVIew1);
                mImageView.setAdjustViewBounds(false);
                mImageView.setScaleType(ImageView.ScaleType.MATRIX);
                mImageView.invalidate();
                break;
            case R.id.ButtonExitEcgPreview:
                //Delete "Preview" scan entry from database as it is not Sent to server.
//bmp 10-Apr-25
//                if(Emergency) {
//                    //Delete EmergencySampleList
//                    int iIndex = alEmergencyScan.size() - 1;
//                    RemoveEmergencySampleFile(iIndex);
//                    alEmergencyScan.remove(iIndex);
//                } else {
//bmp 10-Apr-25
                //Delete sample raw data file
                RemovePatientSampleFile(1);
                alECGScan.remove(1);
                CurrentPatientIndex = 0;
//bmp 10-Apr-25
//                }
//bmp 10-Apr-25
                UpdatePendingSyncSampleList();
/////////////////////////////////////////////
                if (Emergency) {
                    Emergency = false;
                    InitMain();
                } else {
                    setContentView(R.layout.activity_patient_status);
                    CurrentLayoutResourceID = R.layout.activity_patient_status;

                    if (currentPatientType == ESY_G_ONLINE_PATIENT)
                        InitPatientStatus(OnlinePatient);
                    else
                        InitPatientStatus(OfflinePatient);
                }
                getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
                SyncServerEnable = true;
                break;
            case R.id.ButtonPrintA4EcgPreview:
                Button bt = (Button) findViewById(R.id.ButtonExitEcgPreview);
                bt.setEnabled(false);
                bt = (Button) findViewById(R.id.ButtonPrintA4EcgPreview);
                bt.setEnabled(false);
                bt = (Button) findViewById(R.id.ButtonSend);
                bt.setEnabled(false);
                ImageButton imgbt = (ImageButton) findViewById(R.id.imageButtonZoomEcgPreview);
                imgbt.setEnabled(false);
                imgbt = (ImageButton) findViewById(R.id.imageButtonRestoreEcgPreview);
                imgbt.setEnabled(false);
///////////////////////////////////////////
                ReportPatient = currentPatient;
                selectedScan = acqScan;
//                String StrPDFPrePrint = baseDir + "/data/" + "PrePrint" + ".pdf";
                String StrPDFPrePrint = getBaseContext().getCacheDir() + File.separator + "PrePrint" + ".pdf";
                PrintManager printManager = (PrintManager) this.getSystemService(Context.PRINT_SERVICE);
                MyPrintDocumentAdapter pda = new MyPrintDocumentAdapter(this);
                pda.StrFileName = StrPDFPrePrint;
                pda.totalpages = 1;
                pda.PrintECGReportA4Finished = false;
                String jobName = "PrePrint" + ".pdf";
                printManager.print(jobName, pda, null);
///////////////////////////////////////////
                dlgState = ESY_G_DIALOG_STATE_PREPRINT_SUCCESS;
                dlgAlert.setMessage("ECG sent for printing.");
                AlertDialog dialog = dlgAlert.create();
                dialog.show();
                TextView textView = (TextView) dialog.findViewById(android.R.id.message);
                textView.setTextSize(30);
                break;
            case R.id.ButtonSend:
                if (Emergency) {
                    if (EsyGOnline) {
                        RegisterEmergencyPatientResponseAwaited = true;
                        OnlinePatient = EmergencyPatient;
                        if(!WaitingForRegisterPatient) {
                            if(Emergency)
                                RegisterEmergencyPatientResponseAwaited = true;
                            RegisterPatientResponseReceived = false;
                            WaitingForRegisterPatient = true;
                        }
                    } else {
                        //In case not online, emergency patient already registered locally
                    }

                    Emergency = false;
                    InitMain();

                    dlgState = ESY_G_DIALOG_STATE_CONFIRM_ECG_SENT_MSG;
                    dlgAlert.setMessage(MSG_CONFIRM_ECG_SENT);
                    dialog = dlgAlert.create();
                    dialog.show();
                    textView = (TextView) dialog.findViewById(android.R.id.message);
                    textView.setTextSize(30);
                } else {
//bmp 10-Apr-25
//                if(Emergency) {
//                    int iIndex = alEmergencyScan.size() - 1;
//                    alEmergencyScan.get(iIndex).iStatus = SAMPLE_STATUS_COLLECTED;
//                } else {
                alECGScan.get(1).iStatus = SAMPLE_STATUS_COLLECTED;
//                }

                esygDbHelper mDbHelper = new esygDbHelper(getBaseContext());
                // Gets the data repository in write mode
                SQLiteDatabase db = mDbHelper.getWritableDatabase();
                ContentValues values1 = new ContentValues();
                values1.put(esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleStatus, alECGScan.get(1).iStatus);
                String whereClause = esygDbContract.PatientSamplesDB.COLUMN_NAME_PatientSampleList + "=" + "'" + alECGScan.get(1).strScan + "'";
                long lTemp1 = db.update(esygDbContract.PatientSamplesDB.TABLE_NAME, values1, whereClause, null);
                db.close();

                UpdatePendingSyncSampleList();
//bmp 10-Apr-25
                    InitMain();

                    dlgState = ESY_G_DIALOG_STATE_CONFIRM_ECG_SENT_MSG;
                    dlgAlert.setMessage(MSG_CONFIRM_ECG_SENT);
                    dialog = dlgAlert.create();
                    dialog.show();
                    textView = (TextView) dialog.findViewById(android.R.id.message);
                    textView.setTextSize(30);
                }
                getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
                SyncServerEnable = true;
                break;
        }
    }

    public void onClickPatientReports(View v) {
        CustomImageView2 mImageView;
        switch (v.getId()) {
            case R.id.imageButtonRestoreViewReport:
                //restore Imageview to initial state
                mImageView = (CustomImageView2)findViewById(R.id.customImageVIew1);
                mImageView.setAdjustViewBounds(true);
                mImageView.invalidate();
                break;
            case R.id.imageButtonZoomViewReport:
                mImageView = (CustomImageView2)findViewById(R.id.customImageVIew1);
                mImageView.setAdjustViewBounds(false);
                mImageView.setScaleType(ImageView.ScaleType.MATRIX);
                mImageView.invalidate();
                break;
            case R.id.buttonBackReports:
                if(PrevLayoutResourceID == R.layout.activity_sample_status) {
                    setContentView(R.layout.activity_sample_status);
                    CurrentLayoutResourceID = R.layout.activity_sample_status;

                    InitSampleStatus();
                } else {
                    setContentView(R.layout.activity_patient_status);
                    CurrentLayoutResourceID = R.layout.activity_patient_status;

                    if(currentPatientType == ESY_G_ONLINE_PATIENT)
                        InitPatientStatus(OnlinePatient);
                    else
                        InitPatientStatus(OfflinePatient);
                }
                break;
            case R.id.buttonPrintReportA4:
                PrevLayoutResourceID = R.layout.activity_sample_status;
//                String StrPDFPrint = baseDir + "/data/" + selectedScan.strScanFileName + ".pdf";
                String StrPDFPrint = getBaseContext().getCacheDir() + File.separator + selectedScan.strScanFileName + ".pdf";
                PrintManager printManager = (PrintManager) this.getSystemService(Context.PRINT_SERVICE);
                MyPrintDocumentAdapter pda = new MyPrintDocumentAdapter(this);
                pda.StrFileName = StrPDFPrint;
                pda.totalpages = 1;
                pda.PrintECGReportA4Finished = false;
                String jobName = selectedScan.strScanFileName + ".pdf";
                printManager.print(jobName, pda, null);

                int iTemp = alECGScan.get(CurrentPatientIndex).iStatus;
                iTemp |= SAMPLE_STATUS_PRINTED;
                alECGScan.get(CurrentPatientIndex).iStatus = iTemp;
                UpdatePatientSampleFile(CurrentPatientIndex);

                dlgState = ESY_G_DIALOG_STATE_PRINT_SUCCESS;
                dlgAlert.setMessage("ECG sent for printing.");
                AlertDialog dialog = dlgAlert.create();
                dialog.show();
                TextView textView = (TextView) dialog.findViewById(android.R.id.message);
                textView.setTextSize(30);
                break;
            case R.id.buttonEmailReport:

                PrevLayoutResourceID = R.layout.activity_sample_status;

                String StrPDFReportPreview =
                        getBaseContext().getCacheDir()
                                + File.separator
                                + "Preview.pdf";

                File previewFile = new File(StrPDFReportPreview);

                Log.e("PDF_PATH", previewFile.getAbsolutePath());

                if (previewFile.exists() && previewFile.length() > 0) {

                    // Timestamp filename
                    mLastFileName = alECGScan.get(CurrentPatientIndex).strScan;

                    File newPdfFile = new File(
                            getBaseContext().getCacheDir(),
                            mLastFileName + ".pdf"
                    );

                    try {

                        FileInputStream fis = new FileInputStream(previewFile);

                        FileOutputStream fos = new FileOutputStream(newPdfFile);

                        byte[] buffer = new byte[4096];

                        int bytesRead;

                        while ((bytesRead = fis.read(buffer)) != -1) {

                            fos.write(buffer, 0, bytesRead);

                        }

                        fos.flush();

                        fos.getFD().sync();

                        fis.close();

                        fos.close();

                        Log.e("PDF_COPY", "Copy Success");

                    } catch (Exception e) {

                        Log.e("PDF_COPY", "Copy Failed", e);

                    }

                    // Attach timestamp PDF
                    strEmailAttachment = newPdfFile.getAbsolutePath();

                    File finalFile = new File(strEmailAttachment);

                    Log.e("PDF_ATTACH", strEmailAttachment);

                    Log.e("PDF_SIZE", String.valueOf(finalFile.length()));

                    if (finalFile.exists() && finalFile.length() > 0) {

                    EmailReport();

                    dlgState = ESY_G_DIALOG_STATE_PRINT_SUCCESS;
                    dlgAlert.setMessage("Email sent.");
                    dialog = dlgAlert.create();
                    dialog.show();
                    textView = (TextView) dialog.findViewById(android.R.id.message);
                    textView.setTextSize(30);
                    } else {

                        Log.e("PDF_ERROR", "Final PDF corrupted");

                }

                } else {

                    Log.e("PDF_ERROR", "Preview PDF missing or empty");

                    dlgAlert.setMessage("PDF not generated properly.");

                    dialog = dlgAlert.create();

                    dialog.show();

                }

                break;
        }
    }

    public void EmailReport() {

        try {

            Intent sendIntent = new Intent(Intent.ACTION_SEND);

            sendIntent.putExtra(Intent.EXTRA_SUBJECT, "ECG Report");

            sendIntent.putExtra(Intent.EXTRA_TEXT, "Please find attached ECG report.");

        sendIntent.putExtra(Intent.EXTRA_EMAIL, new String[] {strDrEmailAddress});

        sendIntent.putExtra(Intent.EXTRA_CC, new String[] {ReportPatient.strPatient_Mailid});

        File pdfFile = new File(strEmailAttachment);

            Log.e("EMAIL_FILE", pdfFile.getAbsolutePath());

            Log.e("EMAIL_FILE", "Exists = " + pdfFile.exists());

            Log.e("EMAIL_FILE", "Size = " + pdfFile.length());

            if (!pdfFile.exists() || pdfFile.length() <= 0) {

                Toast.makeText(getBaseContext(), "PDF file missing or empty", Toast.LENGTH_LONG).show();

                return;
        }

            Uri senduri = FileProvider.getUriForFile(
                    getApplicationContext(),
                    getApplicationContext().getPackageName() + ".provider",
                    pdfFile
            );

        sendIntent.putExtra(Intent.EXTRA_STREAM, senduri);

            // IMPORTANT
            sendIntent.setType("application/octet-stream");

            sendIntent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);

            // Gmail only
        sendIntent.setPackage("com.google.android.gm");

        dlgState = ESY_G_DIALOG_STATE_NOT_FOREGROUND;

            startActivity(sendIntent);

        } catch (Exception e) {

            Log.e("EMAIL_ERROR", "Email failed", e);

            Toast.makeText(getBaseContext(), "Gmail not installed or Email failed", Toast.LENGTH_LONG).show();
    }
    }

    private void copyFile(File source, File dest) throws IOException {
        try (FileInputStream in = new FileInputStream(source);
             FileOutputStream out = new FileOutputStream(dest)) {

            byte[] buffer = new byte[8192];
            int len;

            while ((len = in.read(buffer)) > 0) {
                out.write(buffer, 0, len);
            }

            out.flush();
        }
    }

