    public boolean GetLogoFromURL() {
        boolean bFlag = false;
        try {
            OkHttpClient client = new OkHttpClient().newBuilder()
                    .readTimeout(15, TimeUnit.SECONDS)
                    .connectTimeout(15, TimeUnit.SECONDS)
                    .build();
            MediaType mediaType = MediaType.parse("text/plain");
            RequestBody body = RequestBody.create(mediaType, "");
            Request request = new Request.Builder()
                    .url(strInstitutionLogoURL)
                    .method("GET", null)
                    .build();
            Response response = client.newCall(request).execute();
            int responseCode = response.code();
            if (responseCode == 200) {
                GetInstitutionLogoResponseReceived = true;
                DataInputStream inData = new DataInputStream(response.body().byteStream());
                byte[] buffer = new byte[4096];
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                int bytesRead = -1;
                int iDownloadBytes = 0;
                while ((bytesRead = inData.read(buffer)) != -1) {
                    baos.write(buffer, 0, bytesRead);
                    iDownloadBytes = iDownloadBytes + bytesRead;
                }
                inData.close();

                byte[] bytearrayInstitutionLogo = baos.toByteArray();

                esygDbHelper mDbHelper = new esygDbHelper(getBaseContext());
                // Gets the data repository in write mode
                SQLiteDatabase db = mDbHelper.getWritableDatabase();

                ContentValues values1 = new ContentValues();
                values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_InstitutionLogo, bytearrayInstitutionLogo);
                // Insert single row, returning the primary key value of the row
                long lTemp1 = db.update(esygDbContract.ConfigMaster.TABLE_NAME, values1, null, null);
                if(lTemp1 <= 0) {
//                    lTemp1 = db.insert(esygDbContract.ConfigMaster.TABLE_NAME, null, values1);
                }

                db.close();

                InstitutionLogoReceived = true;
                bFlag = true;
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return bFlag;
    }
