    public boolean SaveDeviceInfo() {
        boolean bFlag = false;
        String strUrl = "";
        try {
            JSONObject postDataParams = new JSONObject();
            postDataParams.put("AmplifierID", StrHWDeviceID);
            postDataParams.put("ReportingCenterName", strReportingCenter);
            postDataParams.put("OriginatingCenterName", strOriginatingCenter);
            postDataParams.put("PrinterEmailID", strPrinterEmailAddress);
            postDataParams.put("PhysicianEmailID", strDrEmailAddress);
            postDataParams.put("Longitude", strDeviceLongitude);
            postDataParams.put("Latitude", strDeviceLatitude);

            String[] strSplit = strServerIP.split("\\.");
            if(strSplit.length == 4) {
                strUrl = "http://" + strServerIP + NASAN_I2I_URL_savedeviceinfo;
            } else {
                strUrl = "https://" + strServerIP + NASAN_I2I_URL_savedeviceinfo;
            }
            OkHttpClient client = new OkHttpClient().newBuilder()
                    .readTimeout(15, TimeUnit.SECONDS)
                    .connectTimeout(15, TimeUnit.SECONDS)
                    .build();
            MediaType mediaType = MediaType.parse("application/json");
            RequestBody body = RequestBody.create(mediaType, postDataParams.toString());
            Request request = new Request.Builder()
                    .url(strUrl)
                    .method("POST", body)
                    .addHeader("Content-Type", "application/json")
                    .addHeader("token", NasanI2I_Token)
                    .build();
            Response response = client.newCall(request).execute();
            int responseCode = response.code();
            if (responseCode == 200) {
                InputStream in = new BufferedInputStream(response.body().byteStream());
                BufferedReader br = new BufferedReader(new InputStreamReader(in));
                String strOutput;
                while ((strOutput = br.readLine()) != null) {
                    System.out.println(strOutput);
                    JSONObject jo = new JSONObject(strOutput);
                    if (jo.getString("IsSuccess").equalsIgnoreCase("true")) {
                        SaveDeviceInfoResponseReceived = true;
                        bFlag = true;
                    }
                }
                br.close();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return bFlag;
    }
