    public boolean GetDeviceInfo() {
        boolean bFlag = false;
        String strUrl = "";
        try {
            String[] strSplit = strServerIP.split("\\.");
            if(strSplit.length == 4) {
                strUrl = "http://" + strServerIP + NASAN_I2I_URL_getdeviceinfo + StrHWDeviceID;
            } else {
                strUrl = "https://" + strServerIP + NASAN_I2I_URL_getdeviceinfo + StrHWDeviceID;
            }
            OkHttpClient client = new OkHttpClient().newBuilder()
                    .readTimeout(15, TimeUnit.SECONDS)
                    .connectTimeout(15, TimeUnit.SECONDS)
                    .build();
            MediaType mediaType = MediaType.parse("text/plain");
            RequestBody body = RequestBody.create(mediaType, "");
            Request request = new Request.Builder()
                    .url(strUrl)
                    .method("GET", null)
                    .build();
            Response response = client.newCall(request).execute();
            int responseCode = response.code();
            if (responseCode == 200) {
                InputStream in = new BufferedInputStream(response.body().byteStream());
                BufferedReader br = new BufferedReader(new InputStreamReader(in));
                String strOutput;
                while ((strOutput = br.readLine()) != null) {
                    System.out.println(strOutput);
                    JSONObject jo = new JSONObject(strOutput);
                    String strTemp = jo.getString("Response");
                    GetDeviceInfoResponseReceived = true;
                    if (jo.getString("IsSuccess").equalsIgnoreCase("true")) {
                        JSONArray jsonArr = new JSONArray(strTemp);
                        JSONObject sObject = (JSONObject) jsonArr.get(0);
                        try {
                            strI2I_PhysicianName = sObject.get("PhysicianName").toString();
                            strI2I_PhysicianPassword = sObject.get("PhysicianPassword").toString();
                            strI2I_InstitutionGUID = sObject.get("InstitutionGUID").toString();
                            strI2I_FTPUser = sObject.get("FTPUser").toString();
                            strI2I_FTPPassword = sObject.get("FTPPassword").toString();
                            strI2I_FTPPath = sObject.get("FTPPath").toString();

                            strReportingCenter = sObject.get("ReportingCenterName").toString();
                            if(strReportingCenter.length() > 50)
                                strReportingCenter = strReportingCenter.trim().substring(0, 50);
                            strOriginatingCenter = sObject.get("OriginatingCenterName").toString();
                            if(strOriginatingCenter.length() > 50)
                                strOriginatingCenter = strOriginatingCenter.trim().substring(0, 50);
                           /* strPrinterEmailAddress = sObject.get("PrinterEmailID").toString();
                            strDrEmailAddress = sObject.get("PhysicianEmailID").toString();*/
                            String serverPrinterEmail = sObject.optString("PrinterEmailID", "").trim();
                            if (!serverPrinterEmail.isEmpty()) {
                                strPrinterEmailAddress = serverPrinterEmail;
                            }

                            String serverDrEmail = sObject.optString("PhysicianEmailID", "").trim();
                            if (!serverDrEmail.isEmpty()) {
                                strDrEmailAddress = serverDrEmail;
                            }
                            strReportDisclaimer = sObject.get("ReportDisclaimer").toString();

                            strInstitutionLogoURL = sObject.get("InstitutionLogoURL").toString();
                            strInstitutionAddress = sObject.get("InstitutionAddress").toString();
                            strPhysicianAddress = sObject.get("PhysicianAddress").toString();

                            strFTPusername = strI2I_FTPUser;        //I2I_FTP_LOGIN_USER_NAME;
                            strFTPpassword = strI2I_FTPPassword;    //I2I_FTP_LOGIN_PASSWORD;

                            SaveConfig();
                            SaveHWVersion();

                            bFlag = true;
                        } catch (JSONException e) {
                            e.printStackTrace();
                        }
                    }
                }
                br.close();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return bFlag;
    }
