    private View.OnClickListener tablerowSamplesOnClickListener = new View.OnClickListener() {
        public void onClick(View v) {

            if(CurrentViewId > 0) {
                View vPrev = (View) findViewById(CurrentViewId);
                vPrev.setBackgroundColor(Color.BLACK);
            }
            v.setBackgroundColor(Color.argb(128, 0, 255, 255));
            CurrentViewId = v.getId();

            CurrentPatientIndex = (Integer) v.getTag();
            if(CurrentViewId > 0) {
                Button bt = (Button) findViewById(R.id.buttonViewSampleReport);
                bt.setEnabled(true);
            }
        }
    };

    private View.OnClickListener tablerowEventsOnClickListener = new View.OnClickListener() {
        public void onClick(View v) {
            int SelectedEventRow;
//            String SelectedEventType = "";

            if( SelectedEventID != v.getId() ) {    //Ignore multiple clicks
                if (SelectedEventID > 0) {
                    View vPrev = (View) findViewById(SelectedEventID);
                    vPrev.setBackgroundColor(Color.BLACK);
                }
                SelectedEventID = v.getId();
                v.setBackgroundColor(Color.argb(128, 0, 255, 255));

                TableLayout tl = (TableLayout) v.getParent();
                for (int i = 0; i < tl.getChildCount(); i++) {
                    if (SelectedEventID == tl.getChildAt(i).getId()) {
                        SelectedEventRow = i - 1;
//                        SelectedEventType = EventType.get(SelectedEventRow);
                        break;
                    }
                }
            }
        }
    };

    private View.OnClickListener tablerowEmergencyOnClickListener = new View.OnClickListener() {
        public void onClick(View v) {

            if(SelectedEmergencyID > 0) {
                View vPrev = (View) findViewById(SelectedEmergencyID);
                vPrev.setBackgroundColor(Color.BLACK);
            }
            SelectedEmergencyID = v.getId();
            v.setBackgroundColor(Color.argb(128, 0, 255, 255));

            TableLayout tl = (TableLayout) v.getParent();
            for(int i=0; i<tl.getChildCount(); i++) {
                if(SelectedEmergencyID == tl.getChildAt(i).getId()) {
                    SelectedEmergencyRow = i - 1;
                    break;
                }
            }

            Button bt = (Button) findViewById(R.id.buttonLink);
            bt.setEnabled(true);
        }
    };

