    public void onClickPatientIdentity(View v) {
        switch (v.getId()) {
            case R.id.buttonSearch:
                if(getCurrentFocus() != null) {
                    InputMethodManager inputManager = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
                    inputManager.hideSoftInputFromWindow(getCurrentFocus().getWindowToken(), InputMethodManager.HIDE_NOT_ALWAYS);
                }

                TextView tv = (TextView)findViewById(R.id.editTextMobileNumber);
                strSearchPatient_Mobile = tv.getText().toString();

                tv = (TextView)findViewById(R.id.textViewDOB);
                strSearchPatient_DOB = tv.getText().toString();
                if(strSearchPatient_DOB.isEmpty()) {
                    strSearchPatientAge = "";
                } else {
                    Calendar cDOB = Calendar.getInstance();
                    cDOB.set(
                            Integer.parseInt(strSearchPatient_DOB.substring(6, 10)),
                            Integer.parseInt(strSearchPatient_DOB.substring(3, 5)) - 1,
                            Integer.parseInt(strSearchPatient_DOB.substring(0, 2))
                    );
                    Calendar today = Calendar.getInstance();
                    int age = today.get(Calendar.YEAR) - cDOB.get(Calendar.YEAR);
                    if (today.get(Calendar.DAY_OF_YEAR) < cDOB.get(Calendar.DAY_OF_YEAR)) {
                        age--;
                    }
                    strSearchPatientAge = String.valueOf(age);
                }

                tv = (TextView)findViewById(R.id.editTextFirstName);
                strSearchPatient_Fname = tv.getText().toString();
                tv = (TextView)findViewById(R.id.editTextMiddleName);
                strSearchPatient_Mname = tv.getText().toString();
                tv = (TextView)findViewById(R.id.editTextLastName);
                strSearchPatient_Lname = tv.getText().toString();

                tv = (TextView) findViewById(R.id.textViewRecords);
                tv.setText("");

                TableLayout tblSearchResults = (TableLayout) findViewById(R.id.tableLayoutSearchResults);
                int iTemp = tblSearchResults.getChildCount();
                tblSearchResults.removeViews(1, (iTemp-1));

                SelectedPatientID = -1;
                Button bt = (Button) findViewById(R.id.buttonSelect);
                bt.setEnabled(false);

//                ProgressBar pb = (ProgressBar) findViewById(R.id.progressBarPatientIdentity);
//                pb.setVisibility(View.VISIBLE);

//bmp 21-Mar-24
//                if(EsyGOnline) {
                if(EsyGOnline && DeviceInfoReceived) {
//bmp 21-Mar-24
                    //Wait for patient list
                    ProgressBar pb = (ProgressBar) findViewById(R.id.progressBarPatientIdentity);
                    pb.setVisibility(View.VISIBLE);
                    PatientListOnline = true;
//                    AsyncCallWS_getPatientList task = new AsyncCallWS_getPatientList();
//                    task.execute();
                    if(!WaitingForPatientList) {
                        PatientListResponseReceived = false;
                        WaitingForPatientList = true;
                    }
//                } else {    //bmp 04-Nov-2017
//                    //Search local database for patient
//                    PatientListOnline = false;
//                    SQLite_getPatientList();
//bmp 21-Mar-24
                } else {
                    Toast.makeText(getBaseContext(), "Lost Server Connection, please Search Patient again!", Toast.LENGTH_SHORT).show();
                    System.out.println("EsyGOnline: " + String.valueOf(EsyGOnline) + ", DeviceInfoReceived:" + String.valueOf(DeviceInfoReceived));
                }
//                SyncServerEnable = true;
//bmp 21-Mar-24
                break;
            case R.id.buttonSelect:
                //Call Webservice to get patient details
                bt = (Button) findViewById(R.id.buttonSelect);
                bt.setEnabled(false);

//                ProgressBar pb = (ProgressBar) findViewById(R.id.progressBarPatientIdentity);
//                pb.setVisibility(View.VISIBLE);

                if( EsyGOnline && PatientListOnline ) {
                    PatientDetailsOnline = true;

                    OnlinePatient = new clsPatient();
                    OnlinePatient.strPatientID = String.valueOf(SelectedPatientID);
                    SelectedEventID = -1;

                    ProgressBar pb = (ProgressBar) findViewById(R.id.progressBarPatientIdentity);
                    pb.setVisibility(View.VISIBLE);
//                    AsyncCallWS_getPatientDetails task2 = new AsyncCallWS_getPatientDetails();
//                    task2.execute();
                    if(!WaitingForPatientDetails) {
                        PatientDetailsResponseReceived = false;
                        WaitingForPatientDetails = true;
                    }
//                } else if(!PatientListOnline) {   //bmp 04-Nov-2017
//                    PatientDetailsOnline = false;
//
//                    OfflinePatient = new clsPatient();
//                    OfflinePatient.strPatientID = String.valueOf(SelectedPatientID);
//                    SelectedEventID = -1;
//
//                    SQLite_getPatientDetails();
                } else {
                    Toast.makeText(getBaseContext(), "Lost Server Connection, please Search Patient again!", Toast.LENGTH_SHORT).show();
                    PatientListOnline = false;
                    PatientDetailsOnline = false;
//                    if(pb != null)
//                        pb.setVisibility(View.INVISIBLE);

                    InitPatientDOB();
                }
                break;
            case R.id.buttonRegisterNew:
                if(ShortDetails) {
                    setContentView(R.layout.activity_patient_details);
                    CurrentLayoutResourceID = R.layout.activity_patient_details;
                } else {
                    setContentView(R.layout.activity_patient_details);
                    CurrentLayoutResourceID = R.layout.activity_patient_details;
                }

                Emergency = false;
                if( EsyGOnline && PatientListOnline ) {
                    OnlinePatient = new clsPatient();
                    OnlinePatient.strPatientID = "";
                    InitNewPatient(OnlinePatient);

                    currentPatientType = ESY_G_ONLINE_PATIENT;
                    InitPatientDetails(OnlinePatient);

                    PatientDetailsOnline = true;    //bmp added on 28-Nov-2017

//                } else if(!PatientListOnline) {   //bmp 04-Nov-2017
//                    OfflinePatient = new clsPatient();
//                    OfflinePatient.strPatientID = "";
//                    InitNewPatient(OfflinePatient);
//
//                    currentPatientType = ESY_G_OFFLINE_PATIENT;
//                    InitPatientDetails(OfflinePatient);
                } else {
                    Toast.makeText(getBaseContext(), "Lost Server Connection, please Search Patient again!", Toast.LENGTH_SHORT).show();
                    PatientListOnline = false;

                    InitPatientDOB();
                }
                break;
            case R.id.buttonCancel:
                InitMain();
                break;
        }
    }

