    private void InitViewReport() {
        ProgressBar pb = (ProgressBar) findViewById(R.id.progressBarViewReport);
        if(pb != null) {
            pb.setVisibility(View.INVISIBLE);
        }

        if( (alECGScan.get(CurrentPatientIndex).iStatus & SAMPLE_STATUS_DRSIGN_DOWNLOADED) == 0 ) {
//            Button bt = (Button) findViewById(R.id.buttonPrintReportThermal);
//            bt.setEnabled(PrintBeforeSend);
            Button bt = (Button) findViewById(R.id.buttonPrintReportA4);
            bt.setEnabled(PrintBeforeSend);
            bt = (Button) findViewById(R.id.buttonEmailReport);
            bt.setEnabled(PrintBeforeSend);
        } else {
//            Button bt = (Button) findViewById(R.id.buttonPrintReportThermal);
//            bt.setEnabled(true);
            Button bt = (Button) findViewById(R.id.buttonPrintReportA4);
            bt.setEnabled(true);
            bt = (Button) findViewById(R.id.buttonEmailReport);
            bt.setEnabled(true);
        }

        try {
//            String StrPDFReportPreview = baseDir + "/data/" + "Preview" + ".pdf";
            String StrPDFReportPreview = getBaseContext().getCacheDir() + File.separator + "Preview" + ".pdf";
            File imageFile = new File(StrPDFReportPreview);

            // create a new renderer
            renderer = new PdfRenderer(ParcelFileDescriptor.open(imageFile, ParcelFileDescriptor.MODE_READ_ONLY));
            renderer_page = renderer.openPage(0);

            Display display = getWindowManager().getDefaultDisplay();
            DisplayMetrics metrics = new DisplayMetrics();
            display.getMetrics(metrics);
            int DisplayWidth = metrics.widthPixels;
            int DisplayHeight = metrics.heightPixels;

            mBitmap = Bitmap.createBitmap(renderer_page.getWidth(), renderer_page.getHeight(), Bitmap.Config.ARGB_8888);
            renderer_page.render(mBitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);

//            CustomImageView mImageView = (CustomImageView)findViewById(R.id.customImageVIew1);
//            mImageView.setBitmap(mBitmap, DisplayWidth, (int) (0.71f * DisplayWidth));
            CustomImageView2 mImageView = (CustomImageView2)findViewById(R.id.customImageVIew1);
            mImageView.setImageBitmap(mBitmap);
            mImageView.setAdjustViewBounds(true);
            mImageView.invalidate();

            renderer_page.close();
            renderer.close();

            ImageButton imgbtn = (ImageButton) findViewById(R.id.imageButtonZoomViewReport);
            imgbtn.performClick();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void InitPatientDOB() {

        TextView tv = (TextView) findViewById(R.id.textViewDOB);
        String strDate = tv.getText().toString();

        CalendarDOB = Calendar.getInstance();
        if(!strDate.isEmpty()) {
            try {
                CalendarDOB.set(Calendar.DAY_OF_MONTH, Integer.parseInt(strDate.substring(0, 2)));
                CalendarDOB.set(Calendar.MONTH, (Integer.parseInt(strDate.substring(3, 5)) - 1));
                CalendarDOB.set(Calendar.YEAR, Integer.parseInt(strDate.substring(6, 10)));
            }catch (NumberFormatException e) {
                final Calendar c = Calendar.getInstance();
                CalendarDOB.set(Calendar.DAY_OF_MONTH, c.get(Calendar.DAY_OF_MONTH));
                CalendarDOB.set(Calendar.MONTH, c.get(Calendar.MONTH));
                CalendarDOB.set(Calendar.YEAR, (c.get(Calendar.YEAR) - 40));
            }
        } else {
            final Calendar c = Calendar.getInstance();
            CalendarDOB.set(Calendar.DAY_OF_MONTH, c.get(Calendar.DAY_OF_MONTH));
            CalendarDOB.set(Calendar.MONTH, c.get(Calendar.MONTH));
            CalendarDOB.set(Calendar.YEAR, (c.get(Calendar.YEAR) - 40));
        }
        tv.setOnClickListener(new View.OnClickListener() {

            @Override
            public void onClick(View arg0) {

//                DialogFragment newFragment = new SelectDateFragment();
//                newFragment.show(getFragmentManager(), "DatePicker");
                DialogFragment newFragment = new DatePickerFragment();
                newFragment.show(getFragmentManager(), "datePicker");

            }
        });
    }

