    public void SaveConfig() {
        esygDbHelper mDbHelper = new esygDbHelper(getBaseContext());
        // Gets the data repository in write mode
        SQLiteDatabase db = mDbHelper.getWritableDatabase();

        ContentValues values1 = new ContentValues();
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_GainScale, (int)DefaultGainScale);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_SpeedScale, (int)DefaultSpeedScale);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ReportingCenter, strReportingCenter);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_PreviewBeforeSend, String.valueOf(PreviewBeforeSend));
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_PrintBeforeSend, String.valueOf(PrintBeforeSend));
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ColorPrint, String.valueOf(ColorPrint));
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_HRPrint, String.valueOf(HRPrint));
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_BordersPrint, String.valueOf(BordersPrint));
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ReportGridType, ReportGridType);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_LongLead, LongLead);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_QRSLead, QRSLead);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ServerIP, strServerIP);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_PrintGainScale, (int)PrintGainScale);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_PrinterEmailID, strPrinterEmailAddress);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_A4ReportType, A4ReportType);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_A4ReportSubtype, A4ReportSubtype);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_SleepTimeoutMinutes, SleepTimeoutMinutes);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_PendingEmergencyLimit, PendingEmergencyLimit);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_PrintReportFormat, (int)PrintFormat);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ThReportType, ThReportType);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ThPrintDataLengthSec, ThPrintDataLengthSec);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ShortDetails, String.valueOf(ShortDetails));
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_PhysicianEmailID, strDrEmailAddress);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_OriginatingCenterName, strOriginatingCenter);
        values1.put(esygDbContract.ConfigMaster.COLUMN_NAME_ReportDisclaimer, strReportDisclaimer);

        // Insert single row, returning the primary key value of the row
        long lTemp1 = db.update(esygDbContract.ConfigMaster.TABLE_NAME, values1, null, null);
        if(lTemp1 <= 0) {
            lTemp1 = db.insert(esygDbContract.ConfigMaster.TABLE_NAME, null, values1);
        }

        db.close();
    }

