    public void InitSampleStatus() {
        TextView tv;
        int iCount = 0;

        RefreshStatus();

        TableLayout tblSampleLog = (TableLayout) findViewById(R.id.tableLayoutSampleLog);
        int iTemp = tblSampleLog.getChildCount();
        tblSampleLog.removeViews(1, (iTemp-1));
        TextView tvRef = (TextView) findViewById(R.id.textViewSampleLog);

        for(int i=1; i<alECGScan.size(); i++) {
            iCount++;
            TableRow tblRow = new TableRow(getApplicationContext());
            tblRow.setMinimumHeight(50);

            TextView tv1 = new TextView(getApplicationContext());
            if(StrHWDeviceID.length() == 10) {
                tv1.setText(alECGScan.get(i).strScan.substring(11, 21) + " ");
            } else {
                tv1.setText(alECGScan.get(i).strScan.substring(13, 23) + " ");
            }
            tv1.setTextSize(getResources().getDimension(R.dimen.TextSizeSearchResults));
            tv1.setTextColor(tvRef.getTextColors());
            tblRow.addView(tv1);

            TextView tv2 = new TextView(getApplicationContext());
            String Str = alECGScan.get(i).strScan.substring(22, 30);
            if(StrHWDeviceID.length() == 10) {
            } else {
                Str = alECGScan.get(i).strScan.substring(24, 32);
            }
            Str = Str.substring(0, 2) + ":" + Str.substring(3, 5) + ":" + Str.substring(6, 8);
            tv2.setText(Str + " ");
            tv2.setTextSize(getResources().getDimension(R.dimen.TextSizeSearchResults));
            tv2.setTextColor(tvRef.getTextColors());
            tblRow.addView(tv2);

            TextView tv3 = new TextView(getApplicationContext());
            tv3.setText(alECGScan.get(i).strPatient + " ");
            tv3.setTextSize(getResources().getDimension(R.dimen.TextSizeSearchResults));
            tv3.setTextColor(tvRef.getTextColors());
            tblRow.addView(tv3);

            TextView tv4 = new TextView(getApplicationContext());
            String strStatus = "";
            if( (alECGScan.get(i).iStatus & SAMPLE_STATUS_COLLECTED) != 0 )
                strStatus = STR_SAMPLE_STATUS_COLLECTED;
            if( (alECGScan.get(i).iStatus & SAMPLE_STATUS_UPLOADED) != 0 )
                strStatus = STR_SAMPLE_STATUS_UPLOADED;
            if( (alECGScan.get(i).iStatus & SAMPLE_STATUS_REFERRED) != 0 )
                strStatus = STR_SAMPLE_STATUS_REFERRED;
//bmp 30-Nov-24
//            if( (alECGScan.get(i).iStatus & SAMPLE_STATUS_DRSIGN_DOWNLOADED) != 0 )
//                strStatus = STR_SAMPLE_STATUS_COMMENTS_DOWNLOADED;
            if( (alECGScan.get(i).iStatus & SAMPLE_STATUS_COMMENTS_DOWNLOADED) != 0 )
                strStatus = STR_SAMPLE_STATUS_COMMENTS_DOWNLOADED;
            if( (alECGScan.get(i).iStatus & SAMPLE_STATUS_DRSIGN_DOWNLOADED) != 0 )
                strStatus = STR_SAMPLE_STATUS_DRSIGN_DOWNLOADED;
//bmp 30-Nov-24

            tv4.setText(strStatus);
            tv4.setTextSize(getResources().getDimension(R.dimen.TextSizeSearchResults));
            tv4.setTextColor(tvRef.getTextColors());
            tblRow.addView(tv4);

            CheckBox cbPrinted = new CheckBox(getApplicationContext());
            if( (alECGScan.get(i).iStatus & SAMPLE_STATUS_PRINTED) != 0 )
                cbPrinted.setChecked(true);
            else
                cbPrinted.setChecked(false);
            cbPrinted.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    ((CheckBox)v).setChecked(!((CheckBox)v).isChecked());
                }
            });
            tblRow.addView(cbPrinted);

            if(StrHWDeviceID.length() == 10) {
                String strTemp = alECGScan.get(i).strScan.substring(11, 21).substring(0, 2)
                        + alECGScan.get(i).strScan.substring(22, 30).substring(0, 2)
                        + alECGScan.get(i).strScan.substring(22, 30).substring(3, 5)
                        + alECGScan.get(i).strScan.substring(22, 30).substring(6, 8);
                tblRow.setId(Integer.parseInt(strTemp));
            } else {
                String strTemp = alECGScan.get(i).strScan.substring(13, 23).substring(0, 2)
                        + alECGScan.get(i).strScan.substring(24, 32).substring(0, 2)
                        + alECGScan.get(i).strScan.substring(24, 32).substring(3, 5)
                        + alECGScan.get(i).strScan.substring(24, 32).substring(6, 8);
                tblRow.setId(Integer.parseInt(strTemp));
            }

            tblRow.setTag(i);
            tblRow.setOnClickListener(tablerowSamplesOnClickListener);
            tblSampleLog.addView(tblRow);
        }

        tv = (TextView)findViewById(R.id.textViewSampleCount);
        tv.setText(String.valueOf(iCount));
        CurrentViewId = -1;
        CurrentPatientIndex = -1;
        Button bt = (Button) findViewById(R.id.buttonViewSampleReport);
        bt.setEnabled(false);
    }
