    public void InitPatientDetails(clsPatient objPatient) {
        TextView tv;

        RefreshStatus();

        tv = (TextView) findViewById(R.id.editTextPatientName);
        tv.setText(objPatient.strPatient_Fname);
        tv = (TextView) findViewById(R.id.editTextMiddleName);
        tv.setText(objPatient.strPatient_Mname);
        tv = (TextView) findViewById(R.id.editTextLastName);
        tv.setText(objPatient.strPatient_Lname);

        tv = (TextView) findViewById(R.id.textViewDOB);
        tv.setText(objPatient.strPatient_DOB);
        tv = (TextView) findViewById(R.id.editTextAge);
        tv.setText(objPatient.PatientAge);
        EditText ageEditText = (EditText)findViewById(R.id.editTextAge);
        ageEditText.addTextChangedListener(new TextWatcher() {
            @Override
            public void beforeTextChanged(CharSequence s, int start, int count, int after) {

            }

            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {

            }

            @Override
            public void afterTextChanged(Editable s) {
                try {
                    int iYears = Integer.parseInt(s.toString());
                    if(iYears > 110) {
                        iYears = 110;
                        s.replace(0, s.length(), String.valueOf(iYears));
                    }
                    CalendarDOB = Calendar.getInstance();
                    final Calendar c = Calendar.getInstance();
                    CalendarDOB.set(Calendar.DAY_OF_MONTH, c.get(Calendar.DAY_OF_MONTH));
                    CalendarDOB.set(Calendar.MONTH, c.get(Calendar.MONTH));
                    CalendarDOB.set(Calendar.YEAR, (c.get(Calendar.YEAR) - iYears));
                } catch(NumberFormatException e) {
                    s.replace(0, s.length(), "40");
                    final Calendar c = Calendar.getInstance();
                    CalendarDOB.set(Calendar.DAY_OF_MONTH, c.get(Calendar.DAY_OF_MONTH));
                    CalendarDOB.set(Calendar.MONTH, c.get(Calendar.MONTH));
                    CalendarDOB.set(Calendar.YEAR, (c.get(Calendar.YEAR) - 40));
                }
                String strDOB = String.format("%02d", CalendarDOB.get(Calendar.DATE)) + "-" +
                        String.format("%02d", CalendarDOB.get(Calendar.MONTH) + 1) + "-" +
                        String.valueOf(CalendarDOB.get(Calendar.YEAR));
                TextView tv = (TextView) findViewById(R.id.textViewDOB);
                tv.setText(strDOB);
            }
        });

        tv = (TextView) findViewById(R.id.editTextPhoneNo);
        tv.setText(objPatient.strPatient_Mobile);

        RadioGroup rg;
        rg = (RadioGroup)findViewById(R.id.radioGroupGender);
        String Str1 = "Female";
        if( Str1.equalsIgnoreCase(objPatient.strPatient_Gender) )
            rg.check(R.id.radioF);
        else
            rg.check(R.id.radioM);

        tv = (TextView) findViewById(R.id.editTextPinCode);
        tv.setText(objPatient.strPatient_PinCode);

        tv = (TextView) findViewById(R.id.editTextEmail);
        tv.setText(objPatient.strPatient_Mailid);

        tv = (TextView) findViewById(R.id.editTextIDNumber);
        if(objPatient.strIDNumber.equalsIgnoreCase("null")) {
            tv.setText(" ");
        } else {
            tv.setText(objPatient.strIDNumber);
        }

        if(!ShortDetails) {
            tv = (TextView) findViewById(R.id.editTextPhoneNo2);
            tv.setText(objPatient.strPatient_Mobile2);

            tv = (TextView) findViewById(R.id.editTextAddress);
            tv.setText(objPatient.strPatient_Addr1);
            tv = (TextView) findViewById(R.id.editTextAddress2);
            tv.setText(objPatient.strPatient_Addr2);
            tv = (TextView) findViewById(R.id.editTextCity);
            if (objPatient.strPatient_City.equalsIgnoreCase("null")) {
                tv.setText(" ");
            } else {
                tv.setText(objPatient.strPatient_City);
            }

            tv = (TextView) findViewById(R.id.editTextOccupation);
            if (objPatient.strPatientOccupation.equalsIgnoreCase("null")) {
                tv.setText(" ");
            } else {
                tv.setText(objPatient.strPatientOccupation);
            }

            CheckBox cb = (CheckBox) findViewById(R.id.checkBoxIsInsured);
            cb.setChecked(objPatient.bIsInsured);

            ArrayAdapter<String> adapterState = new ArrayAdapter<String>(
                    this,
                    android.R.layout.simple_spinner_item,
                    StateMaster
            );
            adapterState.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);

            Spinner spinnerState = (Spinner) findViewById(R.id.spinnerState);
            spinnerState.setAdapter(adapterState);
            spinnerState.setOnItemSelectedListener(this);
            spinnerState.setEnabled(true);
            spinnerState.setClickable(true);

            TextView textViewState = (TextView) findViewById(R.id.textViewState);
            textViewState.setOnClickListener(v -> spinnerState.performClick());

            try {
                int iTemp = Integer.parseInt(objPatient.strPatient_State);

                for (int i = 0; i < StateIDMaster.size(); i++) {
                    if (iTemp == StateIDMaster.get(i)) {
                        spinnerState.setSelection(i);
                        break;
                    }
                }
            } catch (NumberFormatException e) {
                if (StateMaster.size() > 0) {
                    spinnerState.setSelection(0);
                }
            }


            ArrayAdapter<String> adapterCountry = new ArrayAdapter<String>(
                    this,
                    android.R.layout.simple_spinner_item,
                    CountryMaster
            );
            adapterCountry.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);

            Spinner spinnerCountry = (Spinner) findViewById(R.id.spinnerCountry);
            spinnerCountry.setAdapter(adapterCountry);
            spinnerCountry.setOnItemSelectedListener(this);
            spinnerCountry.setEnabled(true);
            spinnerCountry.setClickable(true);

            TextView textViewCountry = (TextView) findViewById(R.id.textViewCountry);
            textViewCountry.setOnClickListener(v -> spinnerCountry.performClick());

            try {
                int iTemp = Integer.parseInt(objPatient.strPatient_CountryID);

                for (int i = 0; i < CountryIDMaster.size(); i++) {
                    if (iTemp == CountryIDMaster.get(i)) {
                        spinnerCountry.setSelection(i);
                        break;
                    }
                }
            } catch (NumberFormatException e) {
                if (CountryMaster.size() > 0) {
                    spinnerCountry.setSelection(0);
                }
            }


            ArrayAdapter<String> adapterInsuranceProvider = new ArrayAdapter<String>(
                    this,
                    android.R.layout.simple_spinner_item,
                    InsuranceProviderMaster
            );
            adapterInsuranceProvider.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);

            Spinner spinnerInsuranceProvider = (Spinner) findViewById(R.id.spinnerInsuranceProviderID);
            spinnerInsuranceProvider.setAdapter(adapterInsuranceProvider);
            spinnerInsuranceProvider.setOnItemSelectedListener(this);

            try {
                int iTemp = Integer.parseInt(objPatient.strInsuranceProviderID);

                for (int i = 0; i < InsuranceProviderIDMaster.size(); i++) {
                    if (iTemp == InsuranceProviderIDMaster.get(i)) {
                        spinnerInsuranceProvider.setSelection(i);
                        break;
                    }
                }
            } catch (NumberFormatException e) {
                objPatient.strInsuranceProviderID = "1";

                if (InsuranceProviderMaster.size() > 0) {
                    spinnerInsuranceProvider.setSelection(0);
                }
            }

            spinnerInsuranceProvider.invalidate();

            spinnerInsuranceProvider.setEnabled(objPatient.bIsInsured);
            spinnerInsuranceProvider.setClickable(objPatient.bIsInsured);

            TextView textViewInsuranceProvider = (TextView) findViewById(R.id.textViewInsuranceProvider);
            textViewInsuranceProvider.setOnClickListener(v -> {
                if (spinnerInsuranceProvider.isEnabled()) {
                    spinnerInsuranceProvider.performClick();
                }
            });

            spinnerInsuranceProvider.invalidate();
        }

        InitPatientDOB();

//        InputMethodManager imm = (InputMethodManager) getSystemService(Context.INPUT_METHOD_SERVICE);
//        imm.showSoftInput(tv, InputMethodManager.SHOW_IMPLICIT);
    }

