    public void UpdatePatient() {
        String strUrl = "";
        try {
            JSONObject postDataParams = new JSONObject();
            postDataParams.put("PatientID", OnlinePatient.strPatientID);
            postDataParams.put("Patient_Fname", OnlinePatient.strPatient_Fname);
            postDataParams.put("Patient_Mname", OnlinePatient.strPatient_Mname);
            postDataParams.put("Patient_Lname", OnlinePatient.strPatient_Lname);
            String[] strSplit = OnlinePatient.strPatient_DOB.split("-");
            String strPatient_DOB_I2I = strSplit[2] + "-" + strSplit[1] + "-" + strSplit[0] + "T00:00:00";
            postDataParams.put("Patient_DOB", strPatient_DOB_I2I);
            postDataParams.put("Patient_Gender", OnlinePatient.strPatient_Gender);
            postDataParams.put("Patient_Mobile1", OnlinePatient.strPatient_Mobile);
            postDataParams.put("Patient_Mobile2", OnlinePatient.strPatient_Mobile2);
            postDataParams.put("Patient_Mailid", OnlinePatient.strPatient_Mailid);
            postDataParams.put("Patient_Addr1", OnlinePatient.strPatient_Addr1);
            postDataParams.put("Patient_Addr2", OnlinePatient.strPatient_Addr2);
            postDataParams.put("Patient_City", OnlinePatient.strPatient_City);
            postDataParams.put("Patient_PinCode", OnlinePatient.strPatient_PinCode);
            postDataParams.put("IDNumber", OnlinePatient.strIDNumber);
            postDataParams.put("IDType", OnlinePatient.strIDType);
            postDataParams.put("IsInsured", OnlinePatient.bIsInsured);
            postDataParams.put("InsuranceProviderID", OnlinePatient.strInsuranceProviderID);

            String[] strSplit4 = strServerIP.split("\\.");
            if(strSplit4.length == 4) {
                strUrl = "http://" + strServerIP + NASAN_I2I_URL_updatepatient;
            } else {
                strUrl = "https://" + strServerIP + NASAN_I2I_URL_updatepatient;
            }
            OkHttpClient client = new OkHttpClient().newBuilder()
                    .readTimeout(15, TimeUnit.SECONDS)
                    .connectTimeout(15, TimeUnit.SECONDS)
                    .build();
            MediaType mediaType = MediaType.parse("application/json");
            RequestBody body = RequestBody.create(mediaType, postDataParams.toString());
            Request request = new Request.Builder()
                    .url(strUrl)
                    .method("POST", body)
                    .addHeader("Content-Type", "application/json")
                    .addHeader("token", NasanI2I_Token)
                    .build();
            Response response = client.newCall(request).execute();
            int responseCode = response.code();
            if (responseCode == 200) {
                InputStream in = new BufferedInputStream(response.body().byteStream());
                BufferedReader br = new BufferedReader(new InputStreamReader(in));
                String strOutput;
                while ((strOutput = br.readLine()) != null) {
                    System.out.println(strOutput);
                    JSONObject jo = new JSONObject(strOutput);
                    if (jo.getString("IsSuccess").equalsIgnoreCase("true")) {
                        String strTemp = jo.getString("Response");
                        if(strTemp.equalsIgnoreCase(OnlinePatient.strPatientID)) {
                            UpdatePatientResponseReceived = true;
                        }
                    }
                }
                br.close();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
