        values1.put(esygDbContract.SearchMaster.COLUMN_NAME_Patient_DOB, OfflinePatient.strPatient_DOB);
        values1.put(esygDbContract.SearchMaster.COLUMN_NAME_Patient_Mobile1, OfflinePatient.strPatient_Mobile);
        values1.put(esygDbContract.SearchMaster.COLUMN_NAME_Patient_Mobile2, OfflinePatient.strPatient_Mobile2);
        values1.put(esygDbContract.SearchMaster.COLUMN_NAME_Emergency, String.valueOf(Emergency));

        // Insert the new row, returning the primary key value of the new row
