    @SuppressLint("HandlerLeak")
    Handler RecordBufferFullHandler = new Handler() {

        public void handleMessage(Message msg) {

            switch (msg.what) {
                case 0:
                    if(CurrentLayoutResourceID == R.layout.activity_aquire) {
                        Button button = (Button) findViewById(R.id.ButtonPreviewSend);
                        if(PreviewBeforeSend)
                            button.setText("Preview");
                        else
                            button.setText("Send");
                        button.setEnabled(true);
                        ConfirmSend = false;
                    }
                    break;
                case 1:
                case 2:
                case 3:
                case 4:
                case 5:
                case 6:
                case 7:
                case 8:
                case 9:
                case 10:
                    if(CurrentLayoutResourceID == R.layout.activity_aquire) {
                        Button button = (Button) findViewById(R.id.ButtonPreviewSend);
                        button.setText(String.valueOf(msg.what));
                    }
                    break;
            }

            super.handleMessage(msg);
        }
    };

    public void InitVertexBuffer() {

        try {
            glRenderer.SyncObj.acquire();
        } catch (InterruptedException e) {
            // TODO Auto-generated catch block
            e.printStackTrace();
        }

//        Button button = (Button) findViewById(R.id.ButtonSend);
        Button button = (Button) findViewById(R.id.ButtonPreviewSend);
        button.setEnabled(false);

        glRenderer.line.iColorIndex = QRSLeadIndex;
        glRenderer.line.vertexBuffer.position(0);

        for(int i=0; i<12; i++) {
            glRenderer.line.vertexBuffer.position(VERTEX_POSITION_MIN[i]);
            mPrevLeadDataX[i] = LEAD_XMIN[i];

            for(int j=0; j<LEAD_XSPAN; j++) {
                glRenderer.line.vertexBuffer.put(mPrevLeadDataX[i]);
                mPrevLeadDataX[i] = (float) (mPrevLeadDataX[i] + VERTEX_X_STEP);
                glRenderer.line.vertexBuffer.put(LEAD_YOFFSET[i]);
                glRenderer.line.vertexBuffer.put(0);
            }
            mPrevLeadDataX[i] = LEAD_XMIN[i];
            mVertexPosition[i] = VERTEX_POSITION_MIN[i];
        }

        glRenderer.line.vertexBuffer.position(0);
        glSurfaceView.requestRender();

        mNewDataCount = 0;
        mMaxDataCount = 0;
        mWriteLeadDataIndex = 0;
        mRecordBufferFull = false;
        mCountDown = 10;
        mWritePlotDataIndex = 0;
        mReadPlotDataIndex = 0;
        mPlotState = PLOT1;
        for(BufferInWriteIndex=0; BufferInWriteIndex<BUFFERIN_LENGTH; BufferInWriteIndex++) {
            BufferInByteCount[BufferInWriteIndex] = 0;
            for(int i=0; i<BufferIn[BufferInWriteIndex].length; i++) {
                BufferIn[BufferInWriteIndex][i] = 0;
            }
        }
        BufferInReadIndex = 0;
        BufferInWriteIndex = 0;
        BufferInCount = 0;

        glRenderer.SyncObj.release();
    }

