    public static void ProcessDataReceived() {
        int i, j, k, iTemp1, Count, Gain, Speed, LeadIndex;
        float flVertexY;
        int PlotCount = 0;

        Count = mNewDataCount;

        Gain = GAIN_HALF_Q15;		//(1/5)*(1/2)=0.1 in Q15
        switch(GainScale) {
            case -1:
                Gain = GAIN_HALF_Q15;	//(1/5)*(1/2)=0.1 in Q15
                break;
            case 0:
                Gain = GAIN_ONE_Q15;	//(1/5)=0.2 in Q15
                break;
            case 1:
                Gain = GAIN_TWO_Q15;	//(1/5)*(2)=0.4 in Q15
                break;
        }

        Speed = SpeedScale;

        i = Count;
        while(i > 0) {
            switch(Speed) {
                case SPEED_SCALE_LOW:			//Plot1 Skip2
                    switch(mPlotState) {
                        case PLOT1:
                            PlotCount = 1;
                            mPlotState = SKIP1;
                            break;
                        case SKIP1:
                            PlotCount = 0;
                            mPlotState = SKIP2;
                            break;
                        case SKIP2:
                            PlotCount = 0;
                            mPlotState = PLOT1;
                            break;
                    }
                    break;
                case SPEED_SCALE_MEDIUM:		//Plot2 Skip1
                    switch(mPlotState) {
                        case PLOT1:
                            PlotCount = 1;
                            mPlotState = PLOT2;
                            break;
                        case PLOT2:
                            PlotCount = 1;
                            mPlotState = SKIP1;
                            break;
                        case SKIP1:
                            PlotCount = 0;
                            mPlotState = PLOT1;
                            break;
                    }
                    break;
                case SPEED_SCALE_HIGH:			//Plot3 Repeat1
                    switch(mPlotState) {
                        case PLOT1:
                            PlotCount = 1;
                            mPlotState = PLOT2;
                            break;
                        case PLOT2:
                            PlotCount = 1;
                            mPlotState = PLOT3;
                            break;
                        case PLOT3:
                            PlotCount = 2;
                            mPlotState = PLOT1;
                            break;
                    }
                    break;
            }

            for(j=0; j<PlotCount; j++) {
                for(k=0; k<12; k++) {
                    LeadIndex = k;//vnp 2 july 16 LEAD_INDEX[k];
                    iTemp1 = 0;
                    switch(LeadIndex) {
                        case 0:
                            iTemp1 = PlotData0[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 1:
                            iTemp1 = PlotData1[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 2:
                            iTemp1 = PlotData2[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 3:
                            iTemp1 = PlotData3[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 4:
                            iTemp1 = PlotData4[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 5:
                            iTemp1 = PlotData5[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 6:
                            iTemp1 = PlotData6[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 7:
                            iTemp1 = PlotData7[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 8:
                            iTemp1 = PlotData8[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 9:
                            iTemp1 = PlotData9[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 10:
                            iTemp1 = PlotData10[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                        case 11:
                            iTemp1 = PlotData11[mReadPlotDataIndex];
                            iTemp1 = (iTemp1 * Gain) >> 15;
                            iTemp1 = iTemp1 + LEAD_YOFFSET[k];
                            break;
                    }

                    flVertexY = (float)iTemp1/YMAX_POSITIVE;
                    glRenderer.line.vertexBuffer.position(mVertexPosition[k]);
                    glRenderer.line.vertexBuffer.put(mPrevLeadDataX[k]);
                    glRenderer.line.vertexBuffer.put(flVertexY);
                    glRenderer.line.vertexBuffer.put(0);	//VertexZ

                    mPrevLeadDataX[k] = (float) (mPrevLeadDataX[k] + VERTEX_X_STEP);
                    if( mPrevLeadDataX[k] > LEAD_XMAX[k] )
                        mPrevLeadDataX[k] = LEAD_XMIN[k];

                    mVertexPosition[k] = mVertexPosition[k] + 3;
                    if( mVertexPosition[k] > VERTEX_POSITION_MAX[k])
                        mVertexPosition[k] = VERTEX_POSITION_MIN[k];

                    glRenderer.line.RefreshCount++;
                }
            }

            i = i - 1;
            mReadPlotDataIndex = (short) (mReadPlotDataIndex + 1);
            if( mReadPlotDataIndex > MAX_PLOT_BUFFER_INDEX )
                mReadPlotDataIndex = 0;
        }

        glRenderer.line.vertexBuffer.position(0);
        int iTemp = 25;
        switch(SpeedScale) {
            case SPEED_SCALE_LOW:
                iTemp = ECGUpdateIntervalMSec >> 2;		//25;
                break;
            case SPEED_SCALE_MEDIUM:		//25.0mm/sec
                iTemp = ECGUpdateIntervalMSec >> 2;		//25;
                break;
            case SPEED_SCALE_HIGH:
                iTemp = ECGUpdateIntervalMSec >> 1;		//50;
                break;
        }
        if(glRenderer.line.RefreshCount >= iTemp)
            glSurfaceView.requestRender();

        mNewDataReceived = false;
        mNewDataCount = (short) (mNewDataCount - Count);	//mutex?
    }

    public void StartECGDataProcessing() {
        new Thread(new Runnable() {
            public void run() {
                int result;
                byte[] command = new byte[1];

                mCommState = COMM_STATE_VERSION_HEADER;
                mNextByte = 0;
                mNewDataCount = 0;
                mMaxDataCount = 0;
                mWriteLeadDataIndex = 0;
                mRecordBufferFull = false;
                mCountDown = 10;
                mWritePlotDataIndex = 0;
                mReadPlotDataIndex = 0;
                command[0] = COMMAND_START_BYTE;

                while(USBDataStreamIn && (BufferInCount == 0)) {
                    try {
                        mUsbDeviceConnection.bulkTransfer(endpointDataOut, command, 1, 0); //do in another thread
                    } catch (Exception e2) {
                        // TODO Auto-generated catch block
                        e2.printStackTrace();
                    }
                    try {
                        Thread.sleep(100);
//                        Thread.sleep(10);
                    } catch (InterruptedException e) {
                    }
                }

                while (USBDataStreamIn) {
                    if(mUsbDeviceConnection == null) {
                        break;
                    }
                    if( BufferInCount > 0 ) {
//                        System.out.println("BufferInCount= " + String.valueOf(BufferInCount));
//                        System.out.println("BufferInByteCount= " + String.valueOf(BufferInByteCount[BufferInReadIndex]));
                        try {
                            glRenderer.SyncObj.acquire();
                        } catch (InterruptedException e) {
                            // TODO Auto-generated catch block
                            e.printStackTrace();
                        }
//                        while (BufferInCount > 0) {
                            try {
                                mNewDataReceived = true;
                                ParseUSBData(BufferInByteCount[BufferInReadIndex]);
                                if (mNewDataCount > 0)
                                    ProcessDataReceived();
//bmp 04-Apr-24
//                                for(int k=0; k<BufferInByteCount[BufferInReadIndex]; k++)
//                                    BufferIn[BufferInReadIndex][k] = 0;
//bmp 04-Apr-24
                                BufferInReadIndex = BufferInReadIndex + 1;
                                BufferInReadIndex = BufferInReadIndex & BUFFERIN_FOLDBACK;
                                BufferInCount = BufferInCount - 1;
                            } catch (Exception e) {
                                // TODO Auto-generated catch block
                                e.printStackTrace();
                            }
//                        }
                        try {
                            glRenderer.SyncObj.release();
                        } catch (Exception e) {
                            // TODO Auto-generated catch block
                            e.printStackTrace();
                        }
                    } else {
                        try {
    //                        Thread.sleep(10);
                            Thread.sleep(4);
                        } catch (InterruptedException e) {
                        }
                    }
                }
            }
        }
        ).start();
    }
    public void StartECGDataAquisition() {
        new Thread(new Runnable() {
            public void run() {
                int result;
                while (USBDataStreamIn) {
                    if(mUsbDeviceConnection == null) {
                        break;
                    }
                    try {
                        result = mUsbDeviceConnection.bulkTransfer(endpointDataIn, BufferIn[BufferInWriteIndex], BufferIn[BufferInWriteIndex].length, 0);
                        if(BufferInCount < BUFFERIN_LENGTH) {
//                                System.out.println("result = " + String.valueOf(result));
//                                String StrBufferIn = "";
//                                for (int i=0; i<result; i++)
//                                    StrBufferIn = StrBufferIn + String.format(Locale.getDefault(), "%02X", BufferIn[BufferInWriteIndex][i]);
//                                System.out.println("StrBufferIn = " + StrBufferIn);

                                BufferInByteCount[BufferInWriteIndex] = result;
                                BufferInCount = BufferInCount + 1;
                                BufferInWriteIndex = BufferInWriteIndex + 1;
                                BufferInWriteIndex = BufferInWriteIndex & BUFFERIN_FOLDBACK;
                        } else {
                            System.out.println("FT_PURGE_RX");
                        }
                        try {
//                        Thread.sleep(10);
                            Thread.sleep(4);
                        } catch (InterruptedException e) {
                        }
                    } catch (Exception e) {
                        // TODO Auto-generated catch block
                        e.printStackTrace();
                    }
                }
            }
        }
        ).start();
    }

    public void ParseUSBData(int i) {
        int iTemp1;
        short sTemp1;
//        int k = 0;	//Migration to FT311D USB Accessory
        //https://www.ftdichip.com/Support/Knowledgebase/index.html?an232b_04smalldataend.htm
        //The buffer is full (64 bytes made up of 2 status bytes and 62 user bytes).
        int k = 2;

        for(int j = k; j<i; j++) {
//            if(DemoModeAquire) {
//                if(mCommState == COMM_STATE_DATA_PACKET) {
//                    if( mWriteDemoDataIndex > MAX_DEMO_BUFFER_INDEX ) {
//                        mWriteDemoDataIndex = 0;
//                    } else {
//                        DemoData[mWriteDemoDataIndex] = BufferIn[BufferInReadIndex][j];
//                        mWriteDemoDataIndex = (int) (mWriteDemoDataIndex + 1);
//                    }
//                } else {
//                    mWriteDemoDataIndex = 0;
//                }
//            }

            switch(mCommState) {
                case COMM_STATE_VERSION_HEADER:	//1st packet of new communication
                    if(mUsbDeviceConnection != null) { //Ignore data if usb connection is already closed
                        if( BufferIn[BufferInReadIndex][j] == VERSION_PACKET_HEADER ) {
                            mCommState = COMM_STATE_VERSION1;
                        } else {
                            //we missed packet header, switch to higher baudrate anyway
                            mCommState = COMM_STATE_DATA_PACKET;
                            mNextByte = 1;
                            if(mUsbDeviceConnection != null) {
//                					//FT311D USB Accessory does not support on-the-fly baudrate change
                            }
                        }
                    }
                    break;
                case COMM_STATE_VERSION1:
                    if( (BufferIn[BufferInReadIndex][j] > 0) && (BufferIn[BufferInReadIndex][j] < 10) )
                        HWMainVersion = BufferIn[BufferInReadIndex][j];
                    mCommState = COMM_STATE_VERSION2;
                    break;
                case COMM_STATE_VERSION2:
                    if( BufferIn[BufferInReadIndex][j] < 10 )
                        HWSubVersion = BufferIn[BufferInReadIndex][j];
//                    mNextIDByte = 0;
//                    mCommState = COMM_STATE_DEVICE_ID;
                    mCommState = COMM_STATE_DATA_PACKET;
                    mNextByte = 1;
                    break;
                case COMM_STATE_DEVICE_ID:
                    HWDeviceID[mNextIDByte] = BufferIn[BufferInReadIndex][j];
                    mNextIDByte = (short) (mNextIDByte + 1);
                    if( mNextIDByte >= 4) {
                        long lTemp;
                        lTemp = ((long)HWDeviceID[0] & 0x00FF);
                        lTemp = lTemp << 8;
                        lTemp = lTemp | ((long)HWDeviceID[1] & 0x00FF);
                        lTemp = lTemp << 8;
                        lTemp = lTemp | ((long)HWDeviceID[2] & 0x00FF);
                        lTemp = lTemp << 8;
                        lTemp = lTemp | ((long)HWDeviceID[3] & 0x00FF);

                        mCommState = COMM_STATE_DATA_PACKET;
                        mNextByte = 1;
                        if(mUsbDeviceConnection != null) {
                            //FT311D USB Accessory does not support on-the-fly baudrate change
                        }
                    }
                    break;
                case COMM_STATE_DATA_PACKET:
                    switch(mNextByte) {
                        case 1:		//new packet in received msg
                            if( BufferIn[BufferInReadIndex][j] == DATA_PACKET_HEADER ) {
//                                System.out.println("DATA_PACKET_HEADER Found !!!");
                                mNextByte = 2;
                            } else {
                                System.out.println("Missing DATA_PACKET_HEADER: " + String.format(Locale.getDefault(), "%02X", BufferIn[BufferInReadIndex][j]));
                            }
                            break;
                        case 2:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 3;	//(short) (mNextByte + 1);
                            break;
                        case 3:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData1[0] + PrevECGLeadData1[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData1[0] = PrevECGLeadData1[1];
                            PrevECGLeadData1[1] = mShortVal;
                            mShortVal = (short) iTemp1;

                            acqScan.ECGLeadData1[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData1[mWritePlotDataIndex] = mShortVal;
                            mNextByte = 4;	//(short) (mNextByte + 1);
                            break;
                        case 4:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 5;	//(short) (mNextByte + 1);
                            break;
                        case 5:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData2[0] + PrevECGLeadData2[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData2[0] = PrevECGLeadData2[1];
                            PrevECGLeadData2[1] = mShortVal;
                            mShortVal = (short) iTemp1;

                            acqScan.ECGLeadData2[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData2[mWritePlotDataIndex] = mShortVal;
                            mNextByte = 6;	//(short) (mNextByte + 1);
                            break;
                        case 6:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 7;	//(short) (mNextByte + 1);
                            break;
                        case 7:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData6[0] + PrevECGLeadData6[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData6[0] = PrevECGLeadData6[1];
                            PrevECGLeadData6[1] = mShortVal;
                            mShortVal = (short) iTemp1;

//bmp 13-May-25
////bmp 02-May-25
                            acqScan.ECGLeadData6[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData6[mWritePlotDataIndex] = mShortVal;
//                            mShortVal = (short) (0x0800 - mShortVal);
//                            PlotData6[mWritePlotDataIndex] = mShortVal;
//                            acqScan.ECGLeadData6[mWriteLeadDataIndex] = mShortVal;
////bmp 02-May-25
//bmp 13-May-25
                            mNextByte = 8;	//(short) (mNextByte + 1);
                            break;
                        case 8:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 9;	//(short) (mNextByte + 1);
                            break;
                        case 9:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData7[0] + PrevECGLeadData7[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData7[0] = PrevECGLeadData7[1];
                            PrevECGLeadData7[1] = mShortVal;
                            mShortVal = (short) iTemp1;

//bmp 13-May-25
////bmp 02-May-25
                            acqScan.ECGLeadData7[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData7[mWritePlotDataIndex] = mShortVal;
//                            mShortVal = (short) (0x0800 - mShortVal);
//                            PlotData7[mWritePlotDataIndex] = mShortVal;
//                            acqScan.ECGLeadData7[mWriteLeadDataIndex] = mShortVal;
////bmp 02-May-25
//bmp 13-May-25
                            mNextByte = 10;	//(short) (mNextByte + 1);
                            break;
                        case 10:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 11;	//(short) (mNextByte + 1);
                            break;
                        case 11:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData8[0] + PrevECGLeadData8[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData8[0] = PrevECGLeadData8[1];
                            PrevECGLeadData8[1] = mShortVal;
                            mShortVal = (short) iTemp1;

//bmp 13-May-25
////bmp 02-May-25
                            acqScan.ECGLeadData8[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData8[mWritePlotDataIndex] = mShortVal;
//                            mShortVal = (short) (0x0800 - mShortVal);
//                            PlotData8[mWritePlotDataIndex] = mShortVal;
//                            acqScan.ECGLeadData8[mWriteLeadDataIndex] = mShortVal;
////bmp 02-May-25
//bmp 13-May-25
                            mNextByte = 12;	//(short) (mNextByte + 1);
                            break;
                        case 12:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 13;	//(short) (mNextByte + 1);
                            break;
                        case 13:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData9[0] + PrevECGLeadData9[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData9[0] = PrevECGLeadData9[1];
                            PrevECGLeadData9[1] = mShortVal;
                            mShortVal = (short) iTemp1;

//bmp 13-May-25
////bmp 02-May-25
                            acqScan.ECGLeadData9[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData9[mWritePlotDataIndex] = mShortVal;
//                            mShortVal = (short) (0x0800 - mShortVal);
//                            PlotData9[mWritePlotDataIndex] = mShortVal;
//                            acqScan.ECGLeadData9[mWriteLeadDataIndex] = mShortVal;
////bmp 02-May-25
//bmp 13-May-25
                            mNextByte = 14;	//(short) (mNextByte + 1);
                            break;
                        case 14:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 15;	//(short) (mNextByte + 1);
                            break;
                        case 15:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData10[0] + PrevECGLeadData10[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData10[0] = PrevECGLeadData10[1];
                            PrevECGLeadData10[1] = mShortVal;
                            mShortVal = (short) iTemp1;

//bmp 13-May-25
////bmp 02-May-25
                            acqScan.ECGLeadData10[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData10[mWritePlotDataIndex] = mShortVal;
//                            mShortVal = (short) (0x0800 - mShortVal);
//                            PlotData10[mWritePlotDataIndex] = mShortVal;
//                            acqScan.ECGLeadData10[mWriteLeadDataIndex] = mShortVal;
////bmp 02-May-25
//bmp 13-May-25
                            mNextByte = 16;	//(short) (mNextByte + 1);
                            break;
                        case 16:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (sTemp1 << 6);
                            mNextByte = 17;	//(short) (mNextByte + 1);
                            break;
                        case 17:
                            sTemp1 = BufferIn[BufferInReadIndex][j];
                            sTemp1 = (short) (sTemp1 & 0x003F);
                            mShortVal = (short) (mShortVal | sTemp1);

                            iTemp1 = mShortVal + PrevECGLeadData11[0] + PrevECGLeadData11[1];
                            iTemp1 = (iTemp1 * 0x2AAB) >> 15;
                            PrevECGLeadData11[0] = PrevECGLeadData11[1];
                            PrevECGLeadData11[1] = mShortVal;
                            mShortVal = (short) iTemp1;

//bmp 13-May-25
////bmp 02-May-25
                            acqScan.ECGLeadData11[mWriteLeadDataIndex] = mShortVal;
                            mShortVal = (short) (mShortVal - 0x0800);
                            PlotData11[mWritePlotDataIndex] = mShortVal;
//                            mShortVal = (short) (0x0800 - mShortVal);
//                            PlotData11[mWritePlotDataIndex] = mShortVal;
//                            acqScan.ECGLeadData11[mWriteLeadDataIndex] = mShortVal;
////bmp 02-May-25
//bmp 13-May-25

                            //calculate 4 more lead data using formulae
                            //Lead1 = Lead2-Lead3 => ECGLeadData[0]-ECGLeadData[1]
                            PlotData0[mWritePlotDataIndex] = (short) (PlotData1[mWritePlotDataIndex] - PlotData2[mWritePlotDataIndex]);
                            acqScan.ECGLeadData0[mWriteLeadDataIndex] = (short) (PlotData0[mWritePlotDataIndex] + 0x0800);

                            //Lead AVR = (Lead3/2)-Lead2 => (ECGLeadData[1]/2)-ECGLeadData[0]
                            PlotData3[mWritePlotDataIndex] = (short) ((PlotData2[mWritePlotDataIndex] >> 1) - PlotData1[mWritePlotDataIndex]);
                            acqScan.ECGLeadData3[mWriteLeadDataIndex] = (short) (PlotData3[mWritePlotDataIndex] + 0x0800);

                            //Lead AVL = (Lead2/2)-Lead3 => (ECGLeadData[0]/2)-ECGLeadData[1]
                            PlotData4[mWritePlotDataIndex] = (short) ((PlotData1[mWritePlotDataIndex] >> 1) - PlotData2[mWritePlotDataIndex]);
                            acqScan.ECGLeadData4[mWriteLeadDataIndex] = (short) (PlotData4[mWritePlotDataIndex] + 0x0800);

                            //Lead AVF = (Lead2+Lead3)/2 => (ECGLeadData[0]+ECGLeadData[1])/2
                            PlotData5[mWritePlotDataIndex] = (short) ((PlotData1[mWritePlotDataIndex] + PlotData2[mWritePlotDataIndex]) >> 1);
                            acqScan.ECGLeadData5[mWriteLeadDataIndex] = (short) (PlotData5[mWritePlotDataIndex] + 0x0800);

                            mNextByte = 1;
                            mNewDataCount = (short) (mNewDataCount + 1);
                            if( mMaxDataCount < mNewDataCount  )
                                mMaxDataCount = mNewDataCount;
                            if( mNewDataCount > MAX_PLOT_BUFFER_INDEX ) {
//		    					    Toast.makeText(getBaseContext(), "Record Buffer Overflow!",
//		    								Toast.LENGTH_SHORT).show();
                            }
                            mWriteLeadDataIndex = (short) (mWriteLeadDataIndex + 1);
                            if( mWriteLeadDataIndex > MAX_RECORD_BUFFER_INDEX ) {
                                mWriteLeadDataIndex = 0;
//                                mRecordBufferFull = true;
                                if(!mRecordBufferFull) {
                                    mRecordBufferFull = true;
                                    mCountDown = 0;
                                    RecordBufferFullHandler.sendEmptyMessage(mCountDown);
                                }

//                                Date BufferFullTime = new Date();
//                                BufferFullDuration = BufferFullTime.getTime() - LastBufferFullTime.getTime();
//                                LastBufferFullTime = BufferFullTime;
                            }
                            if(!mRecordBufferFull) {
                                if( (mWriteLeadDataIndex % SAMPLES_PER_SEC) == 0 ) {
                                    mCountDown--;
                                    RecordBufferFullHandler.sendEmptyMessage(mCountDown);
                                }
                            }
                            mWritePlotDataIndex = (short) (mWritePlotDataIndex + 1);
                            if( mWritePlotDataIndex > MAX_PLOT_BUFFER_INDEX )
                                mWritePlotDataIndex = 0;
                            break;
                    }
                    break;
            }
        }
    }

    @Override
    public void onItemSelected(AdapterView<?> parent, View view, int position, long id) {
        // TODO Auto-generated method stub
        TextView tv;
        CheckBox cb;
        EditText et;

        switch(parent.getId()) {
            case R.id.spinnerState:
                tv = (TextView) findViewById(R.id.textViewState);
                tv.setText(StateMaster.get(position));
                if(currentPatientType == ESY_G_ONLINE_PATIENT)
                    OnlinePatient.strPatient_State = String.valueOf(StateIDMaster.get(position));
                else
                    OfflinePatient.strPatient_State = String.valueOf(StateIDMaster.get(position));
                break;
            case R.id.spinnerCountry:
                tv = (TextView) findViewById(R.id.textViewCountry);
                tv.setText(CountryMaster.get(position));
                if(currentPatientType == ESY_G_ONLINE_PATIENT)
                    OnlinePatient.strPatient_CountryID = String.valueOf(CountryIDMaster.get(position));
                else
                    OfflinePatient.strPatient_CountryID = String.valueOf(CountryIDMaster.get(position));
                break;
            case R.id.spinnerInsuranceProviderID:
                tv = (TextView) findViewById(R.id.textViewInsuranceProvider);
                if(currentPatientType == ESY_G_ONLINE_PATIENT) {
                    if(OnlinePatient.bIsInsured) {
                        tv.setText(InsuranceProviderMaster.get(position));
                        OnlinePatient.strInsuranceProviderID = String.valueOf(InsuranceProviderIDMaster.get(position));
                    } else {
                        tv.setText(" ");
                        OnlinePatient.strInsuranceProviderID = "1";
                    }
                } else {
                    if(OfflinePatient.bIsInsured) {
                        tv.setText(InsuranceProviderMaster.get(position));
                        OfflinePatient.strInsuranceProviderID = String.valueOf(InsuranceProviderIDMaster.get(position));
                    } else {
                        tv.setText(" ");
                        OfflinePatient.strInsuranceProviderID = "1";
                    }
                }
                break;
        }
    }

